window.QUESTION_BANK = [{"id":"mc001","track":"ai","topic":"机器学习","priority":"必刷","level":"入门","type":"选择","title":"验证集与测试集","question":"选超参数和报告最终泛化成绩分别通常用什么数据？","choices":["测试集与训练集","验证集与独立测试集","训练集与验证集","都用测试集"],"keys":[1],"answer":"在验证集完成调参和模型选择。测试集在方案锁定后使用；反复根据测试结果改模型会让测试集参与选择。"},{"id":"mc002","track":"ai","topic":"机器学习","priority":"必刷","level":"入门","type":"选择","title":"KNN 与特征尺度","question":"如果年龄在 0–100，收入用元表示且可达百万，直接欧氏距离做 KNN 常见问题是什么？","choices":["K 值变为 1","距离必然为负","最近邻对尺度不敏感","收入维度会主导距离"],"keys":[3],"answer":"缩放改变各特征对距离的贡献。标准化的统计量只从训练集拟合，再复用于验证和测试。"},{"id":"mc003","track":"ai","topic":"机器学习","priority":"必刷","level":"入门","type":"选择","title":"K-means 更新规则","question":"使用平方欧氏距离且分簇固定时，簇中心取什么才能最小化簇内平方误差？","choices":["样本均值","逐维最大值","距离原点最近样本","逐维中位数"],"keys":[0],"answer":"对中心求梯度，均值最优。曼哈顿距离对应逐维中位数；空簇需按题意处理。"},{"id":"mc004","track":"ai","topic":"机器学习","priority":"必刷","level":"入门","type":"选择","title":"信息增益","question":"父节点熵 1，两子节点各占 1/4 与 3/4，熵分别为 0 和 0.8，信息增益是多少？","choices":["0.6","0.4","0.8","0.2"],"keys":[1],"answer":"信息增益是父熵减子节点加权熵，1 − 0.25×0 − 0.75×0.8 = 0.4。"},{"id":"mc005","track":"ai","topic":"评估指标","priority":"必刷","level":"入门","type":"选择","title":"不平衡分类指标","question":"TP=20、FP=10、FN=30，正类 F1 约为多少？","choices":["0.40","0.67","0.50","0.25"],"keys":[2],"answer":"F1=2TP/(2TP+FP+FN)=40/80=0.5。多数类比例高时仅看准确率容易掩盖少数类漏检。"},{"id":"mc006","track":"ai","topic":"概率统计","priority":"必刷","level":"入门","type":"选择","title":"贝叶斯后验","question":"某事件先验 1%，检测灵敏度 90%，假阳性率 9%，阳性后的事件概率约是多少？","choices":["99%","9.17%","90%","50%"],"keys":[1],"answer":"P(事件∣阳) = 0.01×0.9/(0.01×0.9+0.99×0.09) ≈ 9.17%。"},{"id":"mc007","track":"ai","topic":"线性代数","priority":"必刷","level":"入门","type":"选择","title":"PCA 的第一主成分","question":"协方差矩阵最大特征值的单位特征向量表示什么？","choices":["数据投影后方差最大的方向","最小方差方向","标签最可分方向","平均样本"],"keys":[0],"answer":"PCA 是无监督线性降维。中心化后协方差最大特征向量最大化投影方差；也能用中心化数据矩阵的 SVD 求解。"},{"id":"mc008","track":"ai","topic":"概率统计","priority":"高频","level":"入门","type":"选择","title":"样本方差更新","question":"Welford 维护了 n、均值和 M2。n>1 时，无偏样本方差是什么？","choices":["M2×n","M2/(n−1)","sqrt(M2/n)","M2/n"],"keys":[1],"answer":"M2 是相对当前均值的平方偏差和。除以 n 得到总体形式的经验方差，除以 n−1 得到通常的无偏样本方差估计。"},{"id":"mc009","track":"ai","topic":"优化与深度学习","priority":"必刷","level":"入门","type":"选择","title":"Adam 状态","question":"标准 Adam 相对基础 SGD 增加的主要统计量是？","choices":["训练集两份副本","梯度的协方差矩阵逆","梯度一阶矩和平方梯度的二阶原点矩的指数滑动平均","Hessian 的完整特征分解"],"keys":[2],"answer":"Adam 为参数维护梯度与梯度平方的指数滑动平均，并通常做偏差修正。"},{"id":"mc010","track":"ai","topic":"优化与深度学习","priority":"必刷","level":"入门","type":"选择","title":"梯度累积","question":"四个等大小 microbatch，各自使用本 batch mean loss。希望梯度等价于合并后计算均值，应怎么做？","choices":["先丢掉前三个梯度","累积时每一步先清梯度","逐个 step，再将参数除以四","每个 loss 除以四再 backward，最后一次 step"],"keys":[3],"answer":"梯度线性叠加。按样本数不相等时应加权；batch 相关算子等也可能影响等价性。"},{"id":"mc011","track":"ai","topic":"优化与深度学习","priority":"必刷","level":"入门","type":"选择","title":"混合精度与 loss scaling","question":"FP16 训练使用动态 loss scaling，主要缓解什么现象？","choices":["序列太长无法截断","验证集泄漏","参数键重名","小梯度下溢"],"keys":[3],"answer":"放大 loss 使反传梯度落入可表示范围，step 前取消缩放；如出现非有限梯度通常跳过迭代并调低 scale。"},{"id":"mc012","track":"ai","topic":"优化与深度学习","priority":"必刷","level":"入门","type":"选择","title":"梯度裁剪","question":"全局 L2 梯度范数为 10、阈值为 2。范数裁剪后梯度怎么变化？","choices":["所有分量在 ±2 各自截断","所有分量减 8","不变","所有分量乘 0.2"],"keys":[3],"answer":"全局范数裁剪按 min(1,阈值/范数) 缩放所有梯度，保留方向。逐元素裁剪是另一种操作。"},{"id":"mc013","track":"ai","topic":"优化与深度学习","priority":"必刷","level":"入门","type":"选择","title":"交叉熵和 logits","question":"分类交叉熵接口已内部做 log-softmax 时，输入应是什么？","choices":["softmax 概率再次送入同接口","argmax 类标","one-hot 概率作为模型输出替代 logits","原始 logits"],"keys":[3],"answer":"把原始分数传给内置稳定计算的交叉熵；先做 softmax 会改变目标函数的数值和梯度。"},{"id":"mc014","track":"ai","topic":"优化与深度学习","priority":"高频","level":"入门","type":"选择","title":"CNN 输出尺寸","question":"输入单轴 32，kernel 3，padding 1，stride 2，dilation 1，输出该轴长度？","choices":["32","16","15","17"],"keys":[1],"answer":"用 floor((L+2P−D(K−1)−1)/S)+1，得到 floor(31/2)+1=16。"},{"id":"mc015","track":"ai","topic":"优化与深度学习","priority":"高频","level":"入门","type":"选择","title":"BatchNorm 评估模式","question":"标准 PyTorch BatchNorm 在 track_running_stats=True 且 eval 时通常使用什么？","choices":["LayerNorm 的隐层均值","训练期间积累的 running mean 和 running variance","模型输入全集的真实均值","当前样本独立统计量"],"keys":[1],"answer":"train 使用 batch 统计量并更新运行统计；eval 通常使用运行统计量。affine 参数仍可应用。"},{"id":"mc016","track":"ai","topic":"大模型","priority":"必刷","level":"入门","type":"选择","title":"Attention 缩放","question":"Scaled Dot-Product Attention 在 softmax 前对 QKᵀ 除以什么？","choices":["token 数","√d_k","头数平方","d_k"],"keys":[1],"answer":"近似独立且单位方差时，点积方差随维数增大，除以 √d_k 可控制分数尺度，缓解 softmax 饱和。"},{"id":"mc017","track":"ai","topic":"大模型","priority":"必刷","level":"入门","type":"选择","title":"因果掩码","question":"自回归模型的第 i 个 query 应屏蔽哪些位置？","choices":["只屏蔽上一句的第一个字符","仅 j=i","所有 j>i","所有 j<i"],"keys":[2],"answer":"当前位置可看到自己及历史；通常把未来位置的 logits 加上负无穷再 softmax。"},{"id":"mc018","track":"ai","topic":"大模型","priority":"必刷","level":"入门","type":"选择","title":"LayerNorm 的统计维度","question":"对形状 [B,T,H] 使用 LayerNorm(H)，均值通常沿哪个维度求？","choices":["批大小 B","把 B 和 T 合并后求一个均值","每个 token 的隐藏维 H","序列 T"],"keys":[2],"answer":"每个样本每个 token 在 H 方向独立归一化，再用可训练的缩放和偏移参数。"},{"id":"mc019","track":"ai","topic":"大模型","priority":"必刷","level":"入门","type":"选择","title":"KV Cache 为什么有效","question":"标准自回归解码中缓存过去 token 的 K、V，主要省掉了什么？","choices":["前缀都不需要预填充","输出 logits 的词表投影","反复投影并重建历史 K/V","每个新 token 的注意力计算都被消除"],"keys":[2],"answer":"历史 K/V 可复用，新 query 仍需读历史缓存并做注意力。长序列下读 KV 可能成为瓶颈。"},{"id":"mc020","track":"ai","topic":"大模型","priority":"必刷","level":"入门","type":"选择","title":"GQA 对 KV 内存的影响","question":"序列长度等条件相同，8 个 query 头共用 2 个 KV 头，相比 8 个 KV 头的 MHA，KV Cache 理论字节数为多少？","choices":["1/2","1/8","1/4","不变"],"keys":[2],"answer":"缓存大小与 KV 头数线性相关，2/8=1/4。按实现和分片可能还有附加开销。"},{"id":"mc021","track":"ai","topic":"大模型","priority":"高频","level":"入门","type":"选择","title":"RAG 与参数更新","question":"常规 RAG 中，让模型参考刚更新的手册，最低限度通常需要哪一步？","choices":["删除原有 prompt","只增大温度","更新索引中的相应文档并做检索","重训模型从零开始"],"keys":[2],"answer":"更新切片和索引后，可检索相关内容并放进上下文。还应检查召回、引用与拒答机制。"},{"id":"mc022","track":"ai","topic":"评估指标","priority":"高频","level":"入门","type":"选择","title":"AUC 的概率解释","question":"不考虑并列时 ROC-AUC 可解释为什么？","choices":["准确率和 F1 的平均","分类阈值的大小","全部预测为正的正确率","随机正样本分数高于随机负样本的概率"],"keys":[3],"answer":"AUC 衡量排序能力。并列时按半分处理；线上正类很稀少时还应关注 PR 曲线及业务阈值指标。"},{"id":"mc023","track":"ai","topic":"大模型","priority":"必刷","level":"入门","type":"选择","title":"Prefill 与 Decode","question":"常见 LLM 在线推理中，典型的 prefill 与逐 token decode 瓶颈倾向是什么？","choices":["decode 越长 KV 读取越少","两者始终锁死在网络 RTT","prefill 不访问显存","prefill 更可能计算密集，decode 更可能带宽受限"],"keys":[3],"answer":"prefill 可并行处理 prompt，矩阵乘规模较大；逐 token decode 常大量读参数与 KV。硬件、批量、序列和实现会改变实际瓶颈。"},{"id":"mc024","track":"ai","topic":"线性代数","priority":"高频","level":"入门","type":"选择","title":"SVD 低秩近似","question":"矩阵做 SVD 后保留最大的 r 个奇异值，得到的截断近似有什么性质？","choices":["保留最小 r 个更好","只能用于方阵","总能无损","在 Frobenius 范数下给出一个最优秩不超过 r 的近似"],"keys":[3],"answer":"Eckart–Young–Mirsky 定理给出最优性，Frobenius 误差平方等于丢弃奇异值的平方和。"},{"id":"mc025","track":"ai","topic":"模型部署","priority":"必刷","level":"入门","type":"选择","title":"量化的计算语义","question":"仿射量化里实际值 x 近似如何由整数 q、scale s 和 zero point z 还原？","choices":["s(q+z)","q/s+z","s(q−z)","s+q−z"],"keys":[2],"answer":"量化通常 q=clip(round(x/s)+z)，反量化为 s(q−z)。每通道或每组可有不同参数。"},{"id":"mc026","track":"ai","topic":"模型部署","priority":"高频","level":"入门","type":"选择","title":"QAT 与 PTQ","question":"QAT 相对常规 PTQ 的关键区别是什么？","choices":["训练或微调时模拟量化误差","只要用 INT8 就一定是 QAT","PTQ 需要完整重训，QAT 不需要","QAT 一律使用更少参数"],"keys":[0],"answer":"QAT 用 fake quant 等模拟量化影响，让模型适应量化。PTQ 在训练后做量化，常需要校准数据。"},{"id":"mc027","track":"ai","topic":"分布式训练","priority":"必刷","level":"入门","type":"选择","title":"ZeRO-3 的分片对象","question":"ZeRO-3 在数据并行组通常分片什么？","choices":["仅输入 token","优化器状态、梯度和模型参数","仅模型参数","仅梯度"],"keys":[1],"answer":"ZeRO-1 分片优化器状态，2 进一步分片梯度，3 再分片参数。分片常换来额外通信及参数聚合管理。"},{"id":"mc028","track":"ai","topic":"分布式训练","priority":"必刷","level":"入门","type":"选择","title":"数据并行梯度","question":"同步的数据并行中，各 rank 样本数相同且各算均值梯度，怎样得到全局均值梯度？","choices":["对每层取最大值","AllGather 后只取最后一份","AllReduce 求和再除 world size","只取 rank 0 梯度"],"keys":[2],"answer":"各 rank 分别计算 local mean。等数量时取 rank 平均即可；不同数量要对样本数加权。"},{"id":"mc029","track":"ai","topic":"数据与概率","priority":"高频","level":"入门","type":"选择","title":"分层抽样","question":"类别极不平衡，希望常规分类随机切分后的 train/val 类别比例接近，优先选什么？","choices":["对验证集过采样再报告原始精度","按标签分层切分","按类标排序后截断","先用全量标签归一化输入"],"keys":[1],"answer":"分层保持类别比例。若数据有同人多记录、时间泄漏风险，组分隔或时间分隔通常更重要。"},{"id":"mc030","track":"ai","topic":"机器学习","priority":"必刷","level":"入门","type":"选择","title":"逻辑回归的阈值","question":"二分类 sigmoid 概率采用 ≥0.5 判正类，等价于对 logit z 用什么条件？","choices":["z≤0","z≥0","z≥1","z≥0.5"],"keys":[1],"answer":"sigmoid 单调，sigmoid(0)=0.5，无需真的计算指数便可在该阈值分类。"},{"id":"mc031","track":"ai","topic":"模型部署","priority":"高频","level":"入门","type":"选择","title":"动态批处理的权衡","question":"加入动态批处理后，最直接的权衡是什么？","choices":["每个请求的 TTFT 一定缩短","所有请求被强制同长度","设备内存必减半","可提升吞吐，却可能因等批增加延迟"],"keys":[3],"answer":"聚合请求能提高利用率，但等待和较大批量可能影响尾延迟；可配置最大等待和 token 预算。"},{"id":"mc032","track":"ai","topic":"机器学习","priority":"高频","level":"中等","type":"选择","title":"L1 与 L2","question":"下列关于 L1、L2 正则的说法哪些对？","choices":["L2 惩罚系数越大一般约束越强","加正则必定提高测试准确率","L1 常促使权重稀疏","L2 在通常定义下连续可微"],"keys":[0,2,3],"answer":"L1 在零点不可微，常产生精确零权重。L2 平滑，通常把权重向零收缩。泛化效果要用独立数据验证。"},{"id":"mc033","track":"ai","topic":"机器学习","priority":"高频","level":"中等","type":"选择","title":"聚类算法边界","question":"哪些陈述成立？","choices":["K-means 可能收敛到局部最优","DBSCAN 可标记噪声点","L1 目标适合按维取中位数","DBSCAN 必须先给定簇数 K"],"keys":[0,1,2],"answer":"DBSCAN 依赖邻域半径和最小邻域样本数，簇数从数据中产生；K-means 对初始化和尺度敏感。"},{"id":"mc034","track":"ai","topic":"机器学习","priority":"必刷","level":"中等","type":"选择","title":"常见数据泄漏","question":"哪些操作会让验证结果偏乐观？","choices":["同一实体的重复样本跨 train 和 val","把上线时不可见的答案字段作特征","全量数据拟合预处理再切分","仅用训练数据拟合标准化"],"keys":[0,1,2],"answer":"预处理统计量、重复实体和未来信息都可能间接泄漏。按训练拟合预处理后再变换验证数据是常规做法。"},{"id":"mc035","track":"ai","topic":"模型部署","priority":"高频","level":"中等","type":"选择","title":"服务指标含义","question":"哪些指标组合可以定位 LLM 请求慢在何处？","choices":["TPOT 或 ITL 反映首 token 后的生成节奏","只看平均 TPS 能直接定位某请求慢在何处","TTFT 表示首 token 等待","P99 与并发负载一起看有助判断尾延时"],"keys":[0,2,3],"answer":"分解排队、prefill、decode 和输出网络时延有助定位；同时固定输入和输出长度分布。"},{"id":"mc036","track":"ai","topic":"大模型","priority":"必刷","level":"中等","type":"选择","title":"Attention 的数值稳定性","question":"下列哪些办法合理？","choices":["softmax 前减该行有效 logits 最大值","mask 后确保普通 softmax 至少有一个有效元素","先对未屏蔽全行 softmax，再只把无效概率清零，总和自然不变","softmax 归约可使用更高累加精度"],"keys":[0,1,3],"answer":"减最大值可保持比例；全 mask 要事先定义行输出。先 softmax 再清零通常丢掉概率质量。"},{"id":"mc037","track":"ai","topic":"大模型","priority":"高频","level":"中等","type":"选择","title":"MoE 路由","question":"关于稀疏 MoE，下列哪些成立？","choices":["要区分 per-token Top-K 和 per-expert 容量","分布式专家并行可能涉及 All-to-All","路由不均会导致热点","MoE 推理每 token 必须经过全部专家"],"keys":[0,1,2],"answer":"稀疏路由只用部分专家；容量策略和负载均衡影响精度、延迟和设备利用率。"},{"id":"mc038","track":"ai","topic":"分布式训练","priority":"必刷","level":"中等","type":"选择","title":"Collective 基本语义","question":"下列哪些成立？","choices":["ReduceScatter 一般把归约结果的一部分分给各 rank","只要同一组 rank，调用顺序不一致也一定能正确结束","AllReduce 后参与 rank 拿到同一归约结果","AllGather 后每个 rank 拿到拼接结果"],"keys":[0,2,3],"answer":"同组通信调用的匹配和顺序需要一致，否则可能挂起或报错。"},{"id":"mc039","track":"ai","topic":"模型部署","priority":"必刷","level":"中等","type":"选择","title":"模型显存组成","question":"训练峰值显存可能包含哪些？","choices":["只需要把权重参数个数乘 dtype 字节","优化器状态","保留的 activation 与临时 workspace","模型参数与梯度"],"keys":[1,2,3],"answer":"估算总量要考虑 shard、复制、内存碎片与峰值并存情况。推理还需考虑 KV cache 和动态批量。"},{"id":"mc040","track":"ai","topic":"优化与深度学习","priority":"必刷","level":"中等","type":"选择","title":"训练不稳定的排查","question":"发现 loss 突然 NaN，优先查哪些？","choices":["输入、标签、log 与除法的非法值","把辅助日志全部关掉即可修复","学习率、混合精度与梯度范数","是否某步骤产生 Inf 梯度"],"keys":[0,2,3],"answer":"逐步定位第一个非有限的张量；比较 FP32 与混精运行，检查 loss 输入和优化器步进。"},{"id":"mc041","track":"ai","topic":"模型部署","priority":"必刷","level":"中等","type":"选择","title":"推理缓存与请求隔离","question":"设计 KV Cache 复用时，哪些条件值得检查？","choices":["复用必须对应一致的 token 前缀","模型和影响 KV 计算的配置应匹配","任意两个文本一样长就可共享 KV","跨租户缓存策略必须考虑隔离"],"keys":[0,1,3],"answer":"缓存键应覆盖与 KV 结果相关的身份与输入因素，隔离策略还要考虑延时侧信道和授权边界。"},{"id":"mc042","track":"ai","topic":"线性代数","priority":"拓展","level":"入门","type":"选择","title":"Cholesky 的要求","question":"对实对称矩阵应用标准 Cholesky，通常要求什么？","choices":["只要有逆就行","正定","对角线全量相同","所有元素都非负"],"keys":[1],"answer":"正定矩阵可分解为 LLᵀ，使用两次三角求解比求逆自然。半正定需谨慎处理零主元。"},{"id":"mc043","track":"ai","topic":"概率统计","priority":"高频","level":"入门","type":"选择","title":"条件独立与朴素贝叶斯","question":"朴素贝叶斯对特征独立的假设是什么？","choices":["各类别的样本数完全一致","永远无条件独立","给定类别后条件独立","标签与每个特征独立"],"keys":[2],"answer":"用给定类别的条件独立把联合似然拆为各维似然乘积。实际特征可相关，模型仍可作为基线。"},{"id":"mc044","track":"ai","topic":"优化与深度学习","priority":"高频","level":"入门","type":"选择","title":"Checkpoint 的代价","question":"激活检查点主要用什么换什么？","choices":["多做一部分前向重算来节省激活显存","网络通信代替控制流","增加优化器状态降低计算","减少参数个数提升精度"],"keys":[0],"answer":"只保留选定边界，反向时重算部分中间激活。涉及随机算子要保证重算语义。"},{"id":"mc045","track":"ai","topic":"大模型","priority":"拓展","level":"中等","type":"选择","title":"温度与 Top-p","question":"关于采样哪些说法对？","choices":["Top-p 先按概率排序再取累计达到阈值的前缀","温度降低通常让非均匀分布更尖锐","beam search 一定适合开放文本创作","贪心等于直接选最大概率 token"],"keys":[0,1,3],"answer":"温度和截断都控制随机性；beam 更适于某些有明确目标结构的生成任务。"},{"id":"mc046","track":"ai","topic":"机器学习","priority":"高频","level":"入门","type":"选择","title":"RANSAC 的基本操作","question":"RANSAC 拟合受离群点污染的数据时，通常先做什么再做什么？","choices":["抽最小候选集拟合，然后全量统计内点","对目标取绝对值后不再抽样","先要求每个点都落入阈值","全量均值后只拟合离群点"],"keys":[0],"answer":"随机取足以估模型的子集，按误差阈值评估全体，选内点最多或得分最佳的模型并常在内点上重拟合。"},{"id":"mc047","track":"ai","topic":"概率统计","priority":"高频","level":"入门","type":"选择","title":"交叉熵与 KL","question":"固定真实分布 p，最小化 H(p,q) 等价于最小化什么？","choices":["二范数必然相等","KL(p‖q)","KL(q‖p)","H(q)"],"keys":[1],"answer":"H(p,q)=H(p)+KL(p‖q)，固定 p 时 H(p) 是常数。q 在 p 为正的支持上为零会导致项发散。"},{"id":"mc048","track":"ai","topic":"模型部署","priority":"高频","level":"中等","type":"选择","title":"低秩适配器","question":"关于 LoRA 下列哪些成立？","choices":["某些部署可离线合并权重","训练参数变少必然使在线 KV Cache 变小","用低秩更新近似 ΔW","典型做法冻结底座权重"],"keys":[0,2,3],"answer":"LoRA 减少适配时的训练参数和相应状态；缓存由模型架构、上下文及精度决定。"},{"id":"mc049","track":"ai","topic":"大模型","priority":"高频","level":"入门","type":"选择","title":"Transformer 位置编码","question":"RoPE 在标准用法中主要作用于什么？","choices":["每个 value 元素都单独做 ReLU","梯度全部求和后的结果","query 和 key","优化器状态"],"keys":[2],"answer":"旋转 query/key 的成对分量，使点积可表达相对位置。实现中要留意缓存位置索引。"},{"id":"aic001","track":"ai","topic":"机器学习","priority":"必刷","level":"中等","type":"编程","title":"KNN 告警分类","question":"输入 n d k，接下来 n 行各含 d 个整数特征及一个整数标签，末行是查询的 d 个特征。取平方欧氏距离最近的 k 个；等距按输入序号，标签票数并列时取标签最小者。1≤k≤n≤10⁵，1≤d≤10。输出预测标签。","example":"输入\n4 2 3\n0 0 2\n1 0 1\n0 1 1\n4 4 2\n0 0\n输出\n1","answer":"求距离时不用开根。把 (距离,序号,标签) 按前两项排序，取前 k 项计数，再按票数降序、标签升序选答案。n 很大且 k 小可使用容量 k 的最大堆。","complexity":"排序 O(nd+n log n) 时间、O(n) 空间；流式最大堆 O(nd+n log(k+1)) 时间、O(k) 额外空间。","code":"import sys\nfrom collections import Counter\n\nread = sys.stdin.buffer.readline\nn, d, k = map(int, read().split())\ntraining = [list(map(int, read().split())) for _ in range(n)]\nquery = list(map(int, read().split()))\n\nneighbors = []\nfor index, row in enumerate(training):\n    distance = sum((row[j] - query[j]) ** 2 for j in range(d))\n    neighbors.append((distance, index, row[d]))\nneighbors.sort()\ncounts = Counter(label for _, _, label in neighbors[:k])\nprint(min(counts, key=lambda label: (-counts[label], label)))"},{"id":"aic002","track":"ai","topic":"机器学习","priority":"必刷","level":"中等","type":"编程","title":"固定轮次 K-means","question":"输入 n d k t，随后 n 行样本、k 行初始中心，每行 d 个实数。执行 t 轮先分配后更新，距离并列取小编号，空簇保留旧中心。按编号输出各中心，每维保留两位小数。n≤2000，d≤10，k≤30，t≤20。","example":"输入\n4 1 2 1\n0\n2\n8\n10\n0\n10\n输出\n1.00\n9.00","answer":"每轮根据旧中心给每点找平方距离最小的簇，同时用 sums 和 counts 累加。所有点处理完后统一更新；空桶跳过。","complexity":"O(tnkd) 时间，O(nd+kd) 空间。","code":"import sys\n\nread = sys.stdin.buffer.readline\nn, d, k, iterations = map(int, read().split())\npoints = [list(map(float, read().split())) for _ in range(n)]\ncenters = [list(map(float, read().split())) for _ in range(k)]\nfor _ in range(iterations):\n    sums = [[0.0] * d for _ in range(k)]\n    counts = [0] * k\n    for point in points:\n        best, best_distance = 0, float(\"inf\")\n        for i, center in enumerate(centers):\n            distance = sum((x - c) ** 2 for x, c in zip(point, center))\n            if distance < best_distance:\n                best, best_distance = i, distance\n        counts[best] += 1\n        for j, value in enumerate(point):\n            sums[best][j] += value\n    for i, count in enumerate(counts):\n        if count:\n            centers[i] = [value / count for value in sums[i]]\n\nfor center in centers:\n    print(\" \".join(f\"{value:.2f}\" for value in center))"},{"id":"aic003","track":"ai","topic":"机器学习","priority":"高频","level":"中等","type":"编程","title":"K-median 鲁棒聚类","question":"输入 n k t，接着 n 行二维整数坐标、k 行初始中心。以 L1 距离分配，平局选小编号，更新每个坐标为簇内下中位数，空簇保持中心。执行 t 轮，输出中心。n≤2000，k≤20，t≤20。","example":"输入\n4 2 1\n0 0\n1 1\n10 10\n12 30\n0 0\n10 10\n输出\n0 0\n10 10","answer":"每轮给样本算所有中心的曼哈顿距离。对每簇分别排序横纵坐标，选下标 (m−1)//2。空簇保持上轮中心。","complexity":"O(t(nk+n log n)) 时间，O(n+k) 空间。"},{"id":"aic004","track":"ai","topic":"机器学习","priority":"高频","level":"中等","type":"编程","title":"DBSCAN 核心点与连通簇","question":"输入 n eps m，随后 n 个二维整数点。距离 ≤eps 的邻域含自身，若邻居数至少 m 则为核心点。只统计互相可达核心点的连通分量数和核心点总数。n≤2000，eps 为非负整数。","example":"输入\n5 2 2\n0 0\n1 0\n10 0\n11 0\n30 0\n输出\n2 4","answer":"第一遍两两算平方距离并记近邻数量，标记核心；第二遍枚举核心点对，邻域相连则 union。非核心点不合并核心簇。","complexity":"O(n² α(n)) 时间，重算距离可把额外空间降到 O(n)。"},{"id":"aic005","track":"ai","topic":"机器学习","priority":"必刷","level":"中等","type":"编程","title":"决策树单维最佳切分","question":"给 n 个 (整数特征, 0/1 标签)，候选是在不同相邻特征间分割，阈值用左侧最大特征表示。找信息增益最大的阈值，同分取最小阈值，无候选输出 NONE。n≤10⁵；相差不超过 1e−12 视为平局。","example":"输入\n4\n1 0\n2 0\n4 1\n7 1\n输出\n2","answer":"按特征排序，扫描维护左右两侧正负样本数。仅在相邻特征不同处计算加权熵，0·log0 按 0 处理。父熵恒定，可以直接最小化加权熵。","complexity":"O(n log n) 时间，O(n) 空间。"},{"id":"aic006","track":"ai","topic":"机器学习","priority":"必刷","level":"中等","type":"编程","title":"线性回归一步更新","question":"给 n 个 (x,y) 实数对，另给 w b η。目标 J=Σ(wx+b−y)²/(2n)。输出一步批量梯度下降后的 w、b，保留四位小数。","example":"输入\n2\n1 2\n2 4\n0 0 0.1\n输出\n0.5000 0.3000","answer":"用旧 w、b 算每个残差 r。分别累加 r*x 和 r，除 n 得对应梯度，同时更新两个参数。","complexity":"O(n) 时间，O(1) 额外空间（若输入参数在样本之后，可存样本或累加充分统计量）。"},{"id":"aic007","track":"ai","topic":"机器学习","priority":"必刷","level":"中等","type":"编程","title":"稳定二分类损失","question":"输入 n，随后 n 行给实数 logit z 和标签 y∈{0,1}。计算平均 sigmoid BCE；z 的绝对值可大至 10⁵，输出六位小数。","example":"输入\n3\n1000 1\n0 1\n-1000 0\n输出\n0.231049","answer":"使用 max(z,0)−z*y+log1p(exp(−abs(z)))，避免显式计算大指数和 log(0)。","complexity":"O(n) 时间，O(1) 额外空间。","code":"import math\nimport sys\n\nread = sys.stdin.buffer.readline\nn = int(read())\ntotal = 0.0\nfor _ in range(n):\n    logit, label = map(float, read().split())\n    total += max(logit, 0.0) - logit * label + math.log1p(math.exp(-abs(logit)))\nprint(f\"{total / n:.6f}\")"},{"id":"aic008","track":"ai","topic":"数值计算","priority":"必刷","level":"中等","type":"编程","title":"稳定 Softmax","question":"给 n 和 n 个实数 logits，输出 softmax，保留六位。n≤10⁵，logits 的绝对值可到 10⁶。","example":"输入\n3\n1000 1000 1000\n输出\n0.333333 0.333333 0.333333","answer":"减最大值后算所有指数，归一化。至少有一项为 exp(0)=1，分母非零。","complexity":"O(n) 时间，O(n) 空间。","code":"import math\nimport sys\n\nn, *tokens = sys.stdin.buffer.read().split()\nlogits = list(map(float, tokens))\nlargest = max(logits)\nweights = [math.exp(value - largest) for value in logits]\ndenominator = sum(weights)\nprint(\" \".join(f\"{value / denominator:.6f}\" for value in weights))"},{"id":"aic009","track":"ai","topic":"数值计算","priority":"必刷","level":"中等","type":"编程","title":"流式均值方差","question":"首行 n，随后逐行给实数，求均值和总体方差，保留六位。n≥1；只允许常数额外空间。","example":"输入\n3\n100000001\n100000002\n100000003\n输出\n100000002.000000 0.666667","answer":"用 Welford。更新前 delta=x−mean，mean+=delta/count，M2+=delta*(x−mean)。最后输出 mean、M2/n。","complexity":"O(n) 时间，O(1) 空间。"},{"id":"aic010","track":"ai","topic":"数值计算","priority":"高频","level":"中等","type":"编程","title":"不平衡分类的宏 F1","question":"首行 n c，随后 n 行给真实和预测类编号 0..c−1。求全部 c 类的宏平均 F1，分母为 0 的类按 0，输出四位小数。","example":"输入\n3 2\n0 0\n0 1\n1 1\n输出\n0.6667","answer":"每类记录真值计数、预测计数、TP。类 F1=2TP/(真实数+预测数)，然后取类平均。避免建完整 c×c 混淆矩阵。","complexity":"O(n+c) 时间，O(c) 空间。"},{"id":"aic011","track":"ai","topic":"数值计算","priority":"高频","level":"中等","type":"编程","title":"一维卷积的互相关","question":"输入 n k p s，第二行 n 个整数，第三行 k 个权重。两侧补 p 个零，窗口长 k，每隔 s 取与权重逐项乘积之和，核保持原顺序。输出全部结果。n≤10⁴，k≤100。","example":"输入\n4 3 1 2\n1 2 3 4\n1 0 -1\n输出\n-2 -2","answer":"有效位置从补零后下标 0 以 s 递增，k 点窗完整时才计算；原数组下标是窗起点加核下标再减 p，越界贡献 zero。","complexity":"O(Lk) 时间，L 为输出长度，输出外空间 O(1)。"},{"id":"aic012","track":"ai","topic":"大模型基础","priority":"必刷","level":"进阶","type":"编程","title":"因果 Attention 单头实现","question":"输入 T d，依次给 Q、K、V，每个 T 行 d 个实数。计算每个位置可见 j≤i 的 scaled dot-product attention，输出 T×d，保留四位。T≤100，d≤64。","example":"输入\n2 1\n0\n0\n2\n3\n2\n4\n输出\n2.0000\n3.0000","answer":"对每一行只计算合法历史分数，除 √d，然后减最大值、归一化。按权重对 V 加权求和；只存一行 logits。","complexity":"O(T²d) 时间，输入和输出之外 O(T+d) 空间。","code":"import math\nimport sys\n\nread = sys.stdin.buffer.readline\nt, d = map(int, read().split())\nq, k, v = [[list(map(float, read().split())) for _ in range(t)] for _ in range(3)]\nscale = math.sqrt(d)\nfor i, query in enumerate(q):\n    scores = [\n        sum(a * b for a, b in zip(query, k[j])) / scale\n        for j in range(i + 1)\n    ]\n    largest = max(scores)\n    weights = [math.exp(score - largest) for score in scores]\n    denominator = sum(weights)\n    result = [\n        sum(weight * v[j][axis] for j, weight in enumerate(weights)) / denominator\n        for axis in range(d)\n    ]\n    print(\" \".join(f\"{value:.4f}\" for value in result))"},{"id":"aic013","track":"ai","topic":"大模型基础","priority":"必刷","level":"中等","type":"编程","title":"LayerNorm 逐行计算","question":"输入 n d eps，第二行 d 个 gamma，第三行 d 个 beta，接着 n 行每行 d 个特征。逐行按总体方差做归一化并仿射，输出保留四位。eps>0。","example":"输入\n1 2 1\n2 1\n0 3\n1 3\n输出\n-1.4142 3.7071","answer":"均值、方差只跨最后一维。令 yⱼ=γⱼ (xⱼ−μ)/sqrt(var+eps)+βⱼ。均值和方差可两遍或 Welford。","complexity":"O(nd) 时间，O(d) 额外空间。"},{"id":"aic014","track":"ai","topic":"AI 场景算法","priority":"必刷","level":"中等","type":"编程","title":"MoE 专家容量路由","question":"输入 n e k cap，随后 n 行 e 个整数分数。每 token 按分数降序、专家编号升序选 k 位候选，按 token 入队顺序尝试，容量满则该路由丢弃，不补位。输出每个专家最终接收数。1≤k≤e≤100，n≤10⁴。","example":"输入\n3 2 1 1\n7 1\n8 2\n3 9\n输出\n1 1","answer":"按 token 顺序处理，在候选上执行容量检测。整理 (负分,编号) 按序取前 k；由于不补位，后续候选不可替代前 k。","complexity":"O(ne log e) 时间，除输入外 O(e) 空间。"},{"id":"aic015","track":"ai","topic":"AI 场景算法","priority":"高频","level":"中等","type":"编程","title":"词表最长前缀分词","question":"给出词表大小 n、接下来 n 个不含空白的词和一个 Unicode 字符串。每次从当前位置取最长匹配词，无匹配消费一个字符并输出 [UNK]。输出空格分隔的 token；最长词长 L≤64，文本长 M≤10⁵。","example":"输入\n3\n推理\n推\n引擎\n推理芯引擎\n输出\n推理 [UNK] 引擎","answer":"用 Trie 存词，从当前位置边走边记录最近终止位置。直到路径断开或文本结束，用记录的最长匹配移动。无匹配至少移动一字符。","complexity":"O(S+ML) 时间，O(S) 除输出空间，S 为词表字符总数。"},{"id":"aic016","track":"ai","topic":"AI 场景算法","priority":"必刷","level":"进阶","type":"编程","title":"流水线分段最短最大耗时","question":"顺序 n 层，第 i 层耗时 tᵢ、显存 mᵢ，均为正整数。切成最多 k 个连续段，每段显存和≤M，求最小的最大段耗时；不可行输出 −1。n≤2×10⁵。首行 n k M，后跟 n 行 tᵢ mᵢ。","example":"输入\n4 2 6\n3 2\n4 3\n5 2\n2 3\n输出\n7","answer":"二分最大耗时 T。对固定 T，每段尽量向右扩直到加下一层违反时间或显存限制；非负代价使最长可行前缀的切法用段数最少。先验证 T=sum(t)，再在 max(t)..sum(t) 找首个可行值。","complexity":"O(n log(sum(t)+1)) 时间，O(n) 空间。","code":"import sys\n\nread = sys.stdin.buffer.readline\nn, k, memory_limit = map(int, read().split())\nlayers = [tuple(map(int, read().split())) for _ in range(n)]\n\n\ndef feasible(time_limit):\n    stages = 1\n    time_used = memory_used = 0\n    for time, memory in layers:\n        if time > time_limit or memory > memory_limit:\n            return False\n        if time_used + time > time_limit or memory_used + memory > memory_limit:\n            stages += 1\n            if stages > k:\n                return False\n            time_used = memory_used = 0\n        time_used += time\n        memory_used += memory\n    return True\n\n\nlow = max(time for time, _ in layers)\nhigh = sum(time for time, _ in layers)\nif not feasible(high):\n    print(-1)\nelse:\n    while low < high:\n        mid = (low + high) // 2\n        if feasible(mid):\n            high = mid\n        else:\n            low = mid + 1\n    print(low)"},{"id":"aic017","track":"ai","topic":"AI 场景算法","priority":"必刷","level":"中等","type":"编程","title":"激活检查点预算选择","question":"n 个独立候选，启用候选 i 要占用 cᵢ 单位额外显存，可节省 vᵢ 单位重算；每项至多取一次。给预算 B，求最大节省。首行 n B，随后 n 行 cᵢ vᵢ。1≤n≤200，1≤cᵢ≤B≤2×10⁴，vᵢ≥0。","example":"输入\n3 5\n2 4\n3 5\n4 7\n输出\n9","answer":"用 0/1 背包。dp[b] 表示预算不超过 b 的最大收益。每个 c,v 对 b 从 B 到 c 倒序更新 dp[b]=max(dp[b],dp[b−c]+v)。","complexity":"O(nB) 时间，O(B) 空间。","code":"import sys\n\nread = sys.stdin.buffer.readline\nn, budget = map(int, read().split())\nsavings = [0] * (budget + 1)\nfor _ in range(n):\n    cost, value = map(int, read().split())\n    for b in range(budget, cost - 1, -1):\n        savings[b] = max(savings[b], savings[b - cost] + value)\nprint(savings[budget])"},{"id":"aic018","track":"ai","topic":"AI 场景算法","priority":"必刷","level":"中等","type":"编程","title":"KV 页预算批处理","question":"输入 n B P，再读 n 行 prompt 长 p、预留生成 g，按队列顺序处理。一个请求独占 ceil((p+g)/P) 页，不与其他请求共享尾页。每批最大 B 页，保持顺序；遇到不能放入当前批的合规请求先结束当前批。超过 B 的请求跳过，不关闭当前批。输出每批请求数，再输出跳过数量。","example":"输入\n5 5 4\n3 1\n7 2\n20 2\n4 3\n10 0\n输出\n2 2\n1","answer":"按整数上取整算页数。维护批当前页数和请求数，超预算请求计跳过数，普通请求放不下时先记录非空批再开新批。最后结算尾批。若无合规请求，第一行留空。","complexity":"O(n) 时间，除输出外 O(1) 空间。"},{"id":"aic019","track":"ai","topic":"AI 场景算法","priority":"高频","level":"中等","type":"编程","title":"告警事件连通聚类","question":"给 n 个设备、m 条同事件关联，另外 q 个查询。首行 n m q，后跟 m 对 a b 及 q 个查询设备 x，输出每次所在簇大小。设备 1..n，n,m,q≤2×10⁵。","example":"输入\n5 3 3\n1 2\n2 4\n3 5\n1\n3\n4\n输出\n3\n2\n3","answer":"用按大小合并和路径压缩的并查集，根维护分量大小。只在不同根合并时累加大小。","complexity":"O((n+m+q)α(n)) 时间，O(n) 空间。"},{"id":"aic020","track":"ai","topic":"AI 场景算法","priority":"高频","level":"中等","type":"编程","title":"向量召回 Top-K","question":"输入 n d k，接着 n 行 d 维实向量和一行查询向量。按余弦相似度从高到低返回 k 个向量的 1 基编号，同分小编号优先；零范数时按相似度 −2，数据保证不同余弦分数相差大于 1e−9。","example":"输入\n3 2 2\n1 0\n1 1\n0 1\n1 0\n输出\n1 2","answer":"预先求查询范数，逐向量算点积和范数。用固定 k 堆保留当前最佳候选，键为 (相似度,−编号)，最后按相似度降序输出。","complexity":"O(nd+n log(k+1)) 时间，若查询先提供可只用 O(k+d) 空间，本输入顺序可存向量 O(nd)。"},{"id":"aic021","track":"ai","topic":"AI 场景算法","priority":"高频","level":"中等","type":"编程","title":"推荐列表的分组重排","question":"首行 n k c，随后 n 行 id 类别 分数。选恰好 k 项，单类别最多 c 项，总分最大；同分时选小 id。输出按分数降序、id 升序的被选 id，不足 k 项输出 −1。","example":"输入\n5 3 1\n1 新闻 10\n2 新闻 9\n3 体育 8\n4 游戏 7\n5 体育 2\n输出\n1 3 4","answer":"全局排序后从前往后，在类别仍有名额时选入。这是分组容量约束；按组只需保留前 c，再在合格并集中取全局 Top-K，故贪心最优。","complexity":"O(n log n) 时间，O(n) 空间。"},{"id":"aic022","track":"ai","topic":"AI 场景算法","priority":"高频","level":"进阶","type":"编程","title":"预算内最优两条 Agent 计划","question":"给 n 个按顺序考察的动作，每个可选或不选，成本为正，收益为非负。求预算 B 内两条不同计划的最高和次高收益，收益可以相同，不够两条次高输出 −1。首行 n B，之后 n 行成本收益。","example":"输入\n3 4\n2 5\n2 5\n3 12\n输出\n12 10","answer":"按用过的预算做 0/1 背包，每格记录前两名且保留相同值的重数。从旧格的选/不选两个不交计划集合取前二。最后从所有可达花费格合并取前二；初始化只有成本 0 的空计划。","complexity":"O(nB) 时间，O(B) 空间。"},{"id":"aic023","track":"ai","topic":"数值计算","priority":"高频","level":"中等","type":"编程","title":"对称 INT8 校准","question":"给 n 与 n 个实数 x。取 s=max(abs(x))/127，全零时输出 s=1。量化为 clamp(round_half_away_from_zero(x/s),−127,127)。先输出 s 六位小数再输出量化序列。","example":"输入\n3\n-127 0 63.5\n输出\n1.000000\n-127 0 64","answer":"先扫描 abs 最大值。计算用未格式化的 s；对非负取 floor(v+0.5)，负数对绝对值取整再加负号，最后截断。","complexity":"O(n) 时间，O(n) 空间。"},{"id":"aic024","track":"ai","topic":"数值计算","priority":"拓展","level":"中等","type":"编程","title":"稀疏矩阵向量乘","question":"输入 r c nnz，随后 nnz 个 (行,列,值) 以 0 开始，下行 c 个向量元素。重复坐标相加。输出 A×v 的 r 个整数；r,c,nnz≤2×10⁵。","example":"输入\n3 2 4\n0 0 1\n0 0 2\n0 1 3\n2 1 4\n5 7\n输出\n36 0 28","answer":"保存稀疏三元组。初始化答案全零，每个三元组执行 ans[row]+=value*v[col]，自然支持重复位置。用 64 位或更大整数视约束而定。","complexity":"O(r+c+nnz) 时间和空间。"},{"id":"aic025","track":"ai","topic":"机器学习","priority":"高频","level":"中等","type":"编程","title":"类别不平衡的 AUC","question":"给 n 条 (整数分数, 0/1 标签)，正负皆有。计算 ROC-AUC，正负分数相同计 0.5。输出六位。n≤2×10⁵。","example":"输入\n4\n2 1\n2 0\n3 1\n1 0\n输出\n0.875000","answer":"按分数升序分组扫描。每组记 p 个正、q 个负，已有较低分负样本 prev，则增加 p*prev+0.5*p*q，最后除以正样本数×负样本数。","complexity":"O(n log n) 时间，O(n) 空间。"},{"id":"aic026","track":"ai","topic":"AI 场景算法","priority":"高频","level":"中等","type":"编程","title":"训练样本均衡分配","question":"输入 n k，跟着 n 个样本大小。需按原顺序把每个样本放到当前负载最少的 worker，同分选最小编号。输出编号顺序的最终负载。","example":"输入\n5 2\n2 5 1 4 3\n输出\n7 8","answer":"最小堆存 (负载,编号)。每个样本弹出堆顶，加当前样本大小再入堆；最后按编号整理。","complexity":"O(k+n log(k+1)) 时间，O(k) 空间。"},{"id":"aic027","track":"ai","topic":"机器学习","priority":"拓展","level":"进阶","type":"编程","title":"用 BIC 选聚类个数","question":"给 n 个观测、m 个候选 (k,LL)，其中 LL 为固定约定下的已算对数似然。假设每个候选参数数 p=3k−1，BIC=p ln(n)−2LL。选 BIC 最小者，差≤1e−10 取更小 k。首行 n m，下跟 m 行 k LL。","example":"输入\n100 2\n2 -100\n3 -92\n输出\n3","answer":"用自然对数。找全局最小 BIC，再在误差范围内选 k 最小者，避免把容差比较当作排序键。","complexity":"O(m) 时间，O(m) 空间；两遍可读时可用 O(1) 额外空间。"},{"id":"aic028","track":"ai","topic":"AI 场景算法","priority":"拓展","level":"中等","type":"编程","title":"事件流 Top-K 频次","question":"输入 n k 后有 n 行事件，每行一个整数 id。最后输出出现频次最高的至多 k 个 id，同频取小 id，按频次降序输出。n≤2×10⁵。","example":"输入\n6 2\n4\n1\n4\n3\n3\n1\n输出\n1 3","answer":"用哈希计频。遍历不同 id，用容量 k 的最小堆按 (频次,−id) 保留最好 k 个，最后排序输出。","complexity":"O(n+u log(k+1)) 时间，O(u+k) 空间，u 是不同 id 数。"},{"id":"alg001","topic":"字符串与模拟","level":"入门","priority":"必刷","type":"编程","title":"压缩连续状态日志","question":"给定长度 1≤n≤10^5 的大写状态串，将每个极大连续段编码为“字符+十进制次数”，次数为 1 也输出。\n输入一行状态串。输出一行编码。","example":"输入\nAAABCCCCA\n输出\nA3B1C4A1","answer":"维护当前段起点，遇到不同字符或到达结尾就输出上一段。","complexity":"时间 O(n)，额外空间 O(1)，不含输出。","track":"algo"},{"id":"alg002","topic":"字符串与模拟","level":"入门","priority":"必刷","type":"编程","title":"清理容器路径","question":"给定长度≤10^5 的绝对路径，“.”表示当前目录，“..”返回上一级且根目录不可再退。忽略重复斜杠，输出规范化路径。","example":"/pool//job/.././out/ → /pool/out","answer":"按斜杠分段，用列表模拟目录栈。普通段入栈，遇“..”且栈非空就弹栈，最后拼接。","complexity":"时间和空间 O(n)。","traps":"... 是普通目录名。","track":"algo"},{"id":"alg003","topic":"字符串与模拟","level":"入门","priority":"高频","type":"编程","title":"规范化指标记录","question":"每行含用逗号分隔的若干 key=value，键和值只含字母数字及两端空格，累计字符数≤10^5。同一键以最后出现为准，按键的字典序输出。","example":"gpu=3, cpu=5, gpu=4 → cpu=5,gpu=4","answer":"切分并去掉两端空格，用哈希表覆盖旧值，再排序键并拼接结果。","complexity":"若有 k 个键，扫描 O(n)，排序 O(k log k) 次键比较，空间 O(n)。","track":"algo"},{"id":"alg004","topic":"字符串与模拟","level":"入门","priority":"高频","type":"编程","title":"作业编号字母匹配","question":"给两个长度≤10^5 的小写串，问能否仅通过重排把第一串变成第二串。","example":"abca, caba → YES； ab, aa → NO","answer":"先比长度，再用 26 个计数统计频差，全部归零才匹配。","complexity":"时间 O(n)，空间 O(1)。","track":"algo"},{"id":"alg005","topic":"字符串与模拟","level":"中等","priority":"高频","type":"编程","title":"交错标识符的合法性","question":"两个组件分别发出串 a、b，总线读到串 c。判断 c 能否保持 a 和 b 各自顺序地交错生成。a、b 长度≤500。","example":"a=ab, b=cd, c=acbd → YES","answer":"令 dp[i][j] 表示 a、b 各使用 i、j 个字符后能否拼出 c 的前 i+j 个字符。根据末尾来自哪一串转移。","complexity":"时间 O(mn)，空间 O(min(m,n))。","traps":"长度先判等；滚动数组需从左向右更新。","track":"algo"},{"id":"alg006","topic":"字符串与模拟","level":"中等","priority":"必刷","type":"编程","title":"解析带括号的部署表达式","question":"表达式含非负整数、空格、二元 + 和 -、圆括号，保证合法且无一元运算。计算其整数值，长度≤10^5。","example":"8-(2-(3+1)) → 10","answer":"维护当前层累计值与运算符。读左括号时保存外层累计值与符号，右括号时将内层结果乘上外层符号并合并。","complexity":"时间 O(n)，空间 O(d)，d 为最大嵌套深度。","traps":"连续数字先读完整再参与运算。","track":"algo"},{"id":"alg007","topic":"字符串与模拟","level":"中等","priority":"高频","type":"编程","title":"执行重复部署指令","question":"解码重复表达式 k[片段]，支持嵌套，字母为原样字符，1≤k≤1000，输入和输出均≤10^5，保证合法。","example":"2[a3[b]] → abbbabbb","answer":"解析为保留引用的序列节点与重复节点。显式栈展开，零长度节点直接跳过，输出时按块收集。可预先求节点长度，压过只有一个非空孩子的序列及重复 1 的节点。","complexity":"避免反复拼接时可做到 O(输入长度+输出长度) 时间，空间 O(输入长度+输出长度)。","traps":"直接在每次出栈复制整段，深层嵌套时不一定线性。","track":"algo"},{"id":"alg008","topic":"字符串与模拟","level":"进阶","priority":"拓展","type":"编程","title":"流式错误码匹配","question":"在长度≤10^6 的日志 s 中找出模式串 p 的所有起点，p 非空且长度≤10^5。允许重叠，输出 0 基位置。","example":"s=ababa, p=aba → [0,2]","answer":"KMP 先算模式串每个前缀的最长真前后缀。扫描日志，失配按前缀表回退，匹配完成也回退以保留重叠。","complexity":"时间 O(n+m)，空间 O(m)，不含输出。","track":"algo"},{"id":"alg009","topic":"哈希与前缀和","level":"入门","priority":"必刷","type":"编程","title":"凑齐两卡显存","question":"n≤10^5 个任务各需要 a[i] 单位显存，找两个不同下标使需求之和为目标 T。保证有解且唯一，返回 0 基下标。","example":"a=[5,1,7,3], T=8 → [1,2]","answer":"从左到右用哈希表记录已见数值及下标，用当前值查询 T−a[i] 后再写入。","complexity":"期望时间 O(n)，空间 O(n)。","traps":"先查后写，避免把元素和自身配对。","track":"algo"},{"id":"alg010","topic":"哈希与前缀和","level":"入门","priority":"高频","type":"编程","title":"首次只出现一次的设备","question":"给定 n≤10^5 个设备 ID，按到达顺序找到第一个全局只出现一次的 ID，无则输出 -1，ID 为非负整数。","example":"[7,3,7,5,3,8] → 5","answer":"第一遍数频次，第二遍找到第一个频次为 1 的 ID。","complexity":"期望时间 O(n)，空间 O(n)。","track":"algo"},{"id":"alg011","topic":"哈希与前缀和","level":"中等","priority":"必刷","type":"编程","title":"净收益恰为预算的批次","question":"给 n≤10^5 个整数，可能为负。统计和恰为 K 的非空连续区间个数。","example":"[1,-1,1], K=1 → 3","answer":"扫描前缀和 S，答案加上此前 S−K 的频次，再插入当前 S；初始空前缀频次为 1。","complexity":"期望时间 O(n)，空间 O(n)。","traps":"元素可负，滑窗不再具有单调性；计数可能超过 32 位。","track":"algo"},{"id":"alg012","topic":"哈希与前缀和","level":"中等","priority":"高频","type":"编程","title":"正负事件等量的最长区间","question":"状态数组只含 0 和 1，n≤10^5，求 0、1 出现次数相同的最长连续区间长度。","example":"[0,1,0,0,1,1] → 6","answer":"把 0 看作 -1，相同前缀和值之间的子数组总和为 0。记每个和第一次出现的位置，访问到时更新最大距离。","complexity":"期望时间 O(n)，空间 O(n)。","track":"algo"},{"id":"alg013","topic":"哈希与前缀和","level":"中等","priority":"高频","type":"编程","title":"批量调整端口配额","question":"n≤10^5 个初值为 0 的端口，m≤10^5 次操作各将闭区间 [l,r] 的值加 x，求最终所有端口值。","example":"n=5，(1,3,+2),(3,5,-1)，下标从 1 开始 → [2,2,1,-1,-1]","answer":"差分数组在 l 加 x，在 r+1 减 x，最后对差分取前缀和。","complexity":"时间 O(n+m)，空间 O(n)。","traps":"开 n+2 长度可免去 r=n 边界分支。","track":"algo"},{"id":"alg014","topic":"哈希与前缀和","level":"中等","priority":"高频","type":"编程","title":"查询丢包热区","question":"给 R×C 丢包计数网格，RC≤10^6，有 Q≤10^5 个 1 基闭矩形查询，求各区间和。","example":"矩阵 [[1,2],[3,4]]，查询 (1,2) 到 (2,2) → 6","answer":"以第 0 行、第 0 列为 0，构造二维前缀和。查询用右下总和减去上方与左方，再加回左上重叠。","complexity":"预处理 O(RC)，每次 O(1)，空间 O(RC)。","track":"algo"},{"id":"alg015","topic":"双指针与滑窗","level":"入门","priority":"必刷","type":"编程","title":"最长无重复请求段","question":"给定长度≤10^5 的字符串，求不含重复字符的最长连续子串长度。","example":"abcaadc → 3","answer":"用哈希表记每个字符最近位置；遇到窗口内的重复字符，左端跳到上次位置之后且不后退。","complexity":"期望时间 O(n)，空间 O(字符种类数)。","track":"algo"},{"id":"alg016","topic":"双指针与滑窗","level":"中等","priority":"必刷","type":"编程","title":"最短吞吐达标窗口","question":"给 n≤10^5 个非负采样值，T>0，求累计值至少 T 的最短连续窗口长度，无则返回 0。","example":"[2,1,5,1,3], T=7 → 3","answer":"右端右移累加，达标时不断尝试收缩左端并更新最短值。非负性保证指针均可只往前。","complexity":"时间 O(n)，空间 O(1)。","track":"algo"},{"id":"alg017","topic":"双指针与滑窗","level":"中等","priority":"高频","type":"编程","title":"至多两类模型的最长窗口","question":"给定长度 n≤10^5 的模型 ID 列表，求只含至多两种 ID 的最长连续区间长度。","example":"[1,2,1,3,3,3,1] → 5","answer":"维护窗口内各 ID 频次。超过两种就移动左端并删除频次归零的项，恢复合法后更新最优。","complexity":"期望时间 O(n)，空间 O(1)。","track":"algo"},{"id":"alg018","topic":"双指针与滑窗","level":"中等","priority":"必刷","type":"编程","title":"三节点负载抵消","question":"有 n≤3000 个带符号负载，找出所有和为 0 的无序值三元组，每组使用三个不同下标，按值去重。","example":"[-2,-1,0,1,2,2] → [[-2,0,2],[-1,0,1]]","answer":"排序，枚举首元素，剩余部分双指针向内夹；找到后跳过重复左右值，首元素也跳过重复。","complexity":"时间 O(n²)，空间取决于排序，不含输出。","track":"algo"},{"id":"alg019","topic":"双指针与滑窗","level":"中等","priority":"高频","type":"编程","title":"覆盖全部告警类的最短片段","question":"给定事件串 s 和一个非空需求串 t，找 s 中覆盖 t 所有字符及重数的最短子串。若同长取最先出现，无解返回空串。两串总长度≤10^5。","example":"s=AXBBCA, t=ABC → BCA","answer":"记录需求频次与尚缺的字符总量。窗口扩展直到覆盖，收缩左端找最短；移走某字符致欠缺时停止收缩。","complexity":"期望时间 O(n+m)，空间 O(字符种类数)。","track":"algo"},{"id":"alg020","topic":"排序、区间与二分","level":"入门","priority":"必刷","type":"编程","title":"合并节点占用时间","question":"给 n≤10^5 个闭区间 [l,r]，合并有交集的区间，按左端排序输出。","example":"[[1,3],[3,5],[7,8]] → [[1,5],[7,8]]","answer":"按左端排序；新左端≤当前右端时更新右端最大值，否则输出当前段并开启下一段。","complexity":"时间 O(n log n)，额外空间取决于排序，不含输出。","track":"algo"},{"id":"alg021","topic":"排序、区间与二分","level":"中等","priority":"必刷","type":"编程","title":"最少并发 GPU 数","question":"给 n≤10^5 个运行时间半开区间 [s,e)，s<e，每个任务用一块卡，求峰值并发。","example":"[[0,3],[1,4],[3,6]] → 2","answer":"将起止转成 +1、-1 事件，按时间排序，同一时刻先处理结束。扫描维护当前并发及最大值。","complexity":"时间 O(n log n)，空间 O(n)。","track":"algo"},{"id":"alg022","topic":"排序、区间与二分","level":"中等","priority":"高频","type":"编程","title":"最大可运行作业数","question":"只有一个执行槽，每个作业对应半开区间 [s,e)。n≤10^5，问最多能完整运行多少个彼此不重叠的作业。","example":"[[0,4],[1,2],[2,3],[3,5]] → 3","answer":"按结束时刻排序，选择每个开始不早于已选作业结束的第一个作业。可用交换论证替换任一最优方案的首个作业。","complexity":"时间 O(n log n)，额外空间取决于排序。","track":"algo"},{"id":"alg023","topic":"排序、区间与二分","level":"入门","priority":"必刷","type":"编程","title":"批量查找首个达标延迟","question":"非降序延迟数组 n≤10^5，Q≤10^5 次查询各给阈值 x，返回首个 ≥x 的 0 基下标，找不到返回 n。","example":"a=[1,4,4,9], x=[4,5,10] → [1,3,4]","answer":"每次对半开搜索范围 [0,n) 做 lower_bound。a[mid]<x 则 l=mid+1，否则 r=mid。","complexity":"时间 O(Q log n)，额外空间 O(1)。","track":"algo"},{"id":"alg024","topic":"排序、区间与二分","level":"中等","priority":"必刷","type":"编程","title":"限制流水线分片峰值","question":"按原序把 n≤10^5 个非负任务权重分为恰好 k 个非空连续段，1≤k≤n，最小化最大段和。\n第一行 n k，第二行 n 个权重。输出一个整数。","example":"输入\n5 2\n7 2 5 10 8\n输出\n18","answer":"二分容量，范围从最大元素到总和。贪心尽可能装满后切段，判断所需段数是否≤k。非负数据的可行段可继续拆细补到恰好 k。","complexity":"时间 O(n log(sum−max+1))，空间 O(1)。","track":"algo"},{"id":"alg025","topic":"排序、区间与二分","level":"中等","priority":"高频","type":"编程","title":"模型副本尽量分散","question":"n≤10^5 个互异机位坐标，上面放 k 个副本，2≤k≤n，最大化任意两副本的最小间距。","example":"[1,2,4,8,9], k=3 → 3","answer":"排序并二分候选最小间距。贪心先放最左机位，再尽早放下一个满足间距的机位，判断能否放 k 个。","complexity":"时间 O(n log n+n log(D+1))，D 为最大坐标差。","track":"algo"},{"id":"alg026","topic":"排序、区间与二分","level":"进阶","priority":"拓展","type":"编程","title":"轮转分桶查找","question":"无重复非降序数组在未知位置旋转，n≤10^5，查询目标下标，不存在返回 -1。","example":"[8,10,1,3,5], x=3 → 3","answer":"每轮判断 mid 左半或右半哪边有序，再看目标是否落在该半的值域中，据此缩小范围。","complexity":"时间 O(log n)，空间 O(1)。","traps":"题设无重复；有重复的变体最坏可能线性。","track":"algo"},{"id":"alg027","topic":"栈、队列与堆","level":"入门","priority":"必刷","type":"编程","title":"检查资源描述符括号","question":"非空字符串只含三种左右括号，长度≤10^5，判断嵌套是否合法。","example":"{[()]} → YES； ([)] → NO","answer":"左括号入栈，右括号必须匹配栈顶；扫描结束要求栈空。","complexity":"时间 O(n)，空间 O(n)。","track":"algo"},{"id":"alg028","topic":"栈、队列与堆","level":"中等","priority":"高频","type":"编程","title":"等待第一个更高负载","question":"给 n≤10^5 个负载值，返回每个位置离右侧第一个严格更大值的距离，不存在用 0。","example":"[3,3,5,4,6] → [2,1,2,1,0]","answer":"用单调栈存待处理下标；当前值严格大于栈顶值时弹出，填距当前的距离，再将当前下标入栈。","complexity":"时间 O(n)，空间 O(n)。","track":"algo"},{"id":"alg029","topic":"栈、队列与堆","level":"中等","priority":"必刷","type":"编程","title":"连续指标峰值","question":"n≤10^5，给负载数组与 1≤k≤n，输出每个长度 k 滑窗的最大值。","example":"[4,2,7,1,6], k=3 → [7,7,7]","answer":"双端队列存下标，队首去过期，队尾删除不大于当前值的下标，入队后用队首作为最大值。","complexity":"时间 O(n)，空间 O(k)，不含输出。","track":"algo"},{"id":"alg030","topic":"栈、队列与堆","level":"中等","priority":"必刷","type":"编程","title":"最常见失败代码","question":"给 n≤10^5 个失败代码及 1≤k≤不同代码数，按频次降序、同频代码升序返回前 k 个。","example":"[3,3,1,1,2,5], k=2 → [1,3]","answer":"哈希计数，把保留的 k 项放入堆；堆顶选成当前最差，即频次最低且同频代码最大。最后对保留项排序。","complexity":"期望时间 O(n+u log(k+1))，空间 O(u+k)，u 为不同代码数。","track":"algo"},{"id":"alg031","topic":"栈、队列与堆","level":"中等","priority":"高频","type":"编程","title":"合流多卡时间线","question":"有 k 个非降序时间戳流，元素总数 N≤10^5，合并成非降序流，同值保留。","example":"[[1,4],[1,3],[]] → [1,1,3,4]","answer":"每条非空流的首元素入最小堆。弹出最小时间戳，推进对应流，再入堆该流下一项。","complexity":"时间 O(k+N log(k+1))，额外空间 O(k)。","track":"algo"},{"id":"alg032","topic":"栈、队列与堆","level":"进阶","priority":"拓展","type":"编程","title":"在线延迟中位数","question":"按顺序加入 n≤10^5 个延迟样本，每次插入后求中位数。偶数个样本取中间两项算术平均值。","example":"[9,1,3,5] → [9,5,3,4]","answer":"用最大堆管理较小一半、最小堆管理较大一半。保持两堆大小差≤1，且较大一半任一值不小于较小一半任一值。","complexity":"单次插入 O(log n)，取中位数 O(1)，空间 O(n)。","traps":"求均值用宽整数或先转换以避免溢出。","track":"algo"},{"id":"alg033","topic":"栈、队列与堆","level":"进阶","priority":"拓展","type":"编程","title":"可分配的最大连续显存块","question":"给非负柱高 n≤10^5，求直方图中能取到的最大轴对齐矩形面积。","example":"[2,1,5,6,2,3] → 10","answer":"栈中保持柱高非降序。遇更低柱时弹栈，当当前柱作为右侧边界时，弹出柱可用宽度为 i−新栈顶−1。最后用 0 高哨兵结算。","complexity":"时间 O(n)，空间 O(n)。","traps":"面积可能需要 64 位；栈空时左边界视为 -1。","track":"algo"},{"id":"alg034","topic":"图搜索与连通性","level":"入门","priority":"必刷","type":"编程","title":"离故障机器最近的跳数","question":"给 n≤10^5 个节点、m≤2×10^5 条无权双向链路和一组故障节点，输出每个节点距最近故障源的最少跳数，不可达为 -1。\n首行 n m k，节点编号 0 到 n−1，接下来 m 行是 u v，末行是 k 个故障节点。输出一行 n 个距离。","example":"输入\n4 3 2\n0 1\n1 2\n2 3\n0 3\n输出\n0 1 1 0","answer":"所有故障点初始化为距离 0 同时入队，多源 BFS 第一次访问到节点即得到最短距离。","complexity":"时间和空间 O(n+m)。","track":"algo"},{"id":"alg035","topic":"图搜索与连通性","level":"入门","priority":"必刷","type":"编程","title":"网格上的机群计数","question":"R×C 网格只含 0、1，RC≤10^6。1 只能与上下左右的 1 连通，求连通块数。","example":"[[1,0,1],[1,1,0]] → 2","answer":"扫描网格，遇到未标记 1 时用 BFS/DFS 标记整块并计数一次。","complexity":"时间 O(RC)，最坏空间 O(RC)。","traps":"斜对角不算连通；大网格用显式栈或队列。","track":"algo"},{"id":"alg036","topic":"图搜索与连通性","level":"中等","priority":"必刷","type":"编程","title":"穿过一次失效链路","question":"给 R×C 网格，0 可通行，1 为障碍，起点终点可通行。允许穿过至多一个障碍，求从左上到右下的最少步数，不可达返回 -1，RC≤10^6。","example":"[[0,1,0],[1,1,0],[0,0,0]] → 4","answer":"将是否已穿过障碍加入状态，BFS 分别维护每格两份访问标记。合法的四邻接转移边权均为 1。","complexity":"时间和空间 O(RC)。","traps":"同一个格子，两种状态不能共用 visited。","track":"algo"},{"id":"alg037","topic":"图搜索与连通性","level":"中等","priority":"必刷","type":"编程","title":"部署依赖和最早顺序","question":"给 n≤10^5 个任务、m≤2×10^5 条先后约束 u→v。返回字典序最小的拓扑顺序；有环时返回空列表。","example":"n=4，边 0→2、1→2、2→3 → [0,1,2,3]","answer":"计算入度，零入度节点放最小堆。反复取最小节点，删边并把新产生的零入度节点入堆；结果不足 n 则有环。","complexity":"时间 O(m+n log(n+1))，空间 O(n+m)。","track":"algo"},{"id":"alg038","topic":"图搜索与连通性","level":"中等","priority":"必刷","type":"编程","title":"最小网络成本","question":"给 n≤10^5 个节点、m≤2×10^5 条有向链路，耗时是非负整数。求源点到各点最小总耗时，不可达为 -1。","example":"0→1=4，0→2=1，2→1=2，源 0 → [0,3,1]","answer":"用 Dijkstra，最小堆取当前最短候选，跳过过期条目，沿边松弛并入堆。","complexity":"时间 O(n+m log(m+1))，空间 O(n+m)。","traps":"负权不能用；可能溢出的距离使用宽整数。","track":"algo"},{"id":"alg039","topic":"图搜索与连通性","level":"中等","priority":"必刷","type":"编程","title":"合并资源池","question":"n≤10^5 个资源池初始互不连通，处理 m≤2×10^5 条合并或连通查询，按查询顺序返回结果。","example":"合并(0,1)，查(0,2)，合并(1,2)，查(0,2) → [NO,YES]","answer":"并查集保存父节点，使用按大小合并和路径压缩。查询比较根。","complexity":"摊还时间 O(n+m α(n))，空间 O(n)。","track":"algo"},{"id":"alg040","topic":"图搜索与连通性","level":"进阶","priority":"高频","type":"编程","title":"给机房铺设最廉价骨干","question":"n≤10^5 个机房和 m≤2×10^5 条备选无向链路，每条有铺设成本。求使全网连通的最小总成本，不可连通返回 -1。","example":"边 0—1=2，0—2=8，1—2=3 → 5","answer":"Kruskal 按边权升序，仅选择连接不同并查集的边，选够 n−1 即完成。","complexity":"时间 O(n+m log(m+1))，空间 O(n+m)。","track":"algo"},{"id":"alg041","topic":"图搜索与连通性","level":"进阶","priority":"拓展","type":"编程","title":"优先走已有高速链路","question":"n≤10^5 个节点，m≤2×10^5 条有向链路。边的改造成本为 0 或 1，求从 s 到 t 的最低改造成本，不可达返回 -1。","example":"0→1 成本1，0→2 成本0，2→1 成本0，s=0,t=1 → 0","answer":"用 0-1 BFS，松弛后成本为 0 的边把终点压队首，成本为 1 的压队尾，以非降序处理距离。","complexity":"时间和空间 O(n+m)。","track":"algo"},{"id":"alg042","topic":"动态规划与贪心","level":"入门","priority":"必刷","type":"编程","title":"不相邻的维护窗口","question":"周期性维护需要冷却，只能选择互不相邻的时段。给 n≤10^5 个非负收益，求可得最大总收益。","example":"[3,2,7,4] → 10","answer":"到 i 的最优值为 max(dp[i−1],dp[i−2]+a[i])，滚动保存两个旧值。","complexity":"时间 O(n)，空间 O(1)。","track":"algo"},{"id":"alg043","topic":"动态规划与贪心","level":"中等","priority":"必刷","type":"编程","title":"显存预算内的模型收益","question":"有 n≤200 个模型，每个最多选一次。权重 w 为正整数，总预算 B≤10^4，求最多总收益。","example":"模型 [权重,收益] 为 [[2,4],[3,5],[4,7]]，B=5 → 9","answer":"0/1 背包。每处理一个物品，容量从 B 向 w 倒序执行 dp[c]=max(dp[c],dp[c−w]+v)。","complexity":"时间 O(nB)，空间 O(B)。","traps":"正序会使本轮状态被重复使用。","track":"algo"},{"id":"alg044","topic":"动态规划与贪心","level":"中等","priority":"高频","type":"编程","title":"最少实例凑齐吞吐","question":"给正整数吞吐档位，种类数 n≤100，每类可用任意次，目标 T≤10^4，求恰好达到 T 所需最少实例数，无解为 -1。","example":"档位 [2,3,7]，T=12 → 3","answer":"令 dp[0]=0，其余无穷。额度从 1 到 T 递增，对每个可用档位 c 取 min(dp[x],dp[x−c]+1)。","complexity":"时间 O(nT)，空间 O(T)。","track":"algo"},{"id":"alg045","topic":"动态规划与贪心","level":"中等","priority":"必刷","type":"编程","title":"最长逐渐增大的吞吐序列","question":"给 n≤10^5 个整数，求严格递增子序列最大长度，下标可跳过。","example":"[7,1,5,2,6,3,8] → 4","answer":"tails[i] 存长度 i+1 的递增子序列的最小尾值。每项二分第一个 ≥它的位置进行替换，找不到则追加。","complexity":"时间 O(n log n)，空间 O(n)。","traps":"tails 不能直接当成原数组中的答案子序列。","track":"algo"},{"id":"alg046","topic":"动态规划与贪心","level":"中等","priority":"高频","type":"编程","title":"配置编辑成本","question":"给两个长度≤1000 的字符串，每次可插入、删除或替换一个字符，代价均为 1，计算最少操作数。","example":"gpu → gpus，答案 1","answer":"dp[i][j] 表示两个前缀的编辑距离。末字符相等则沿对角线，否则取插、删、改三种来源的最小值加 1。","complexity":"时间 O(mn)，空间 O(min(m,n))。","track":"algo"},{"id":"alg047","topic":"动态规划与贪心","level":"中等","priority":"必刷","type":"编程","title":"净吞吐最高的连续段","question":"有 n≤10^5 个正负吞吐差值，求和最大的非空连续子数组的和。","example":"[-6,4,-1,2,-7,3] → 5","answer":"在每个位置比较从当前重开或接上之前的最佳结尾，顺手更新全局最佳值。初始取首元素。","complexity":"时间 O(n)，空间 O(1)。","traps":"全负时答案是最大单个值，不能用 0 初始化答案。","track":"algo"},{"id":"alg048","topic":"动态规划与贪心","level":"中等","priority":"高频","type":"编程","title":"跨机架最小迁移成本","question":"给 R×C 的非负成本网格，只能向右或向下，从左上到右下并包含两端代价。网格元素数≤10^6。","example":"[[1,3,1],[1,5,1],[4,2,1]] → 7","answer":"转移为当前代价加上上方与左方的较小值，边界仅从可达方向转移，按行滚动。","complexity":"时间 O(RC)，空间 O(C)。","track":"algo"},{"id":"alg049","topic":"动态规划与贪心","level":"中等","priority":"高频","type":"编程","title":"最少中转跳数","question":"数组 a[i] 是从 i 开始可向右跳的最大步长，n≤10^5，保证终点可达，求从 0 到 n−1 的最少跳数。","example":"[2,3,1,1,4] → 2","answer":"把每一跳能到达的区间当成一层，扫描本层所有位置更新下一层的最远边界。走到当前边界时才计一次跳跃。","complexity":"时间 O(n)，空间 O(1)。","traps":"扫描到倒数第二项即止，以免到终点后多跳一次。","track":"algo"},{"id":"alg050","topic":"动态规划与贪心","level":"进阶","priority":"高频","type":"编程","title":"可拆分字符串计费","question":"小写字符串长度 n≤10^5，字典总字符数≤10^5，每个词都有非负成本且长度≤32。允许重复用词，求完整切分的最小总成本，无解 -1。","example":"s=aba，字典 a:2、ab:3、ba:4 → 5","answer":"用 Trie 存词及价格。令 dp[i] 为前 i 个字符最低成本，从可达 i 沿 Trie 最多向右走 32 个字符，每遇成词松弛 dp[j+1]。","complexity":"时间 O(字典字符总数+nL)，空间 O(字典字符总数+n)，L 最大词长。","track":"algo"},{"id":"alg051","topic":"树、链表与回溯","level":"入门","priority":"必刷","type":"编程","title":"倒转空闲块链表","question":"给最多 10^5 个节点的无环单链表，原地反转并返回新头，可为空。","example":"1→4→9 → 9→4→1","answer":"保存 next，令当前 next 指向 prev，再移动 prev 和当前指针；返回 prev。","complexity":"时间 O(n)，空间 O(1)。","track":"algo"},{"id":"alg052","topic":"树、链表与回溯","level":"中等","priority":"高频","type":"编程","title":"查找链表中的循环入口","question":"给含至多 10^5 个不同节点的单链表，可能有环；返回环入口节点，无环返回空。","example":"节点依次 2→7→9→4，尾指回值为 7 的节点 → 该 7 节点","answer":"快慢指针首次相遇后，把一个指针移回头，两者同时单步前进，下一次相遇即入口。","complexity":"时间 O(n)，空间 O(1)。","traps":"比较节点身份，节点值可以重复。","track":"algo"},{"id":"alg053","topic":"树、链表与回溯","level":"入门","priority":"必刷","type":"编程","title":"按层检查服务树","question":"二叉树含至多 10^5 个节点，从根开始按层返回节点值，每层从左至右。","example":"层序表示 [3,1,5,null,2] → [[3],[1,5],[2]]","answer":"根入队，每轮固定本轮队列长度，只处理这些节点，再把孩子按左、右顺序入队。","complexity":"时间 O(n)，额外空间 O(w)，w 为最大层宽。","track":"algo"},{"id":"alg054","topic":"树、链表与回溯","level":"中等","priority":"高频","type":"编程","title":"故障节点最近公共上游","question":"给 n≤10^5 个节点的一般二叉树，两个已知不同节点都存在，返回最近公共祖先。","example":"树 [8,3,10,1,6]，节点 1、6 → 节点 3","answer":"单次查询可迭代遍历记父指针。记录第一个节点到根的祖先集合，再从第二个节点向上找第一个命中。","complexity":"时间和空间 O(n)。","traps":"深链形树避免语言默认递归深度限制。","track":"algo"},{"id":"alg055","topic":"树、链表与回溯","level":"中等","priority":"高频","type":"编程","title":"二叉树最长链路","question":"树 n≤10^5，求任意两节点路径上的最大边数。","example":"树 [1,2,3,4,5] → 3","answer":"后序求节点高度。若高度按节点数统计，当前节点作转折点的边数为左右子树高度之和，取全局最大值。","complexity":"时间 O(n)，空间 O(h) 可用显式后序帧。","track":"algo"},{"id":"alg056","topic":"树、链表与回溯","level":"中等","priority":"高频","type":"编程","title":"无重复配置组合","question":"n≤20 的正整数中可能有重复，每个下标最多使用一次。输出和为目标 T 的所有不同无序值组合，组合内升序。","example":"[2,2,3,5], T=7 → [[2,2,3],[2,5]]","answer":"排序后回溯。递归传入下一起始下标，同一递归层只选择每种值的第一个候选；遇候选大于剩余和可停止。","complexity":"时间最坏 O(n·2^n)，递归空间 O(n)，不含输出。","track":"algo"},{"id":"alg057","topic":"树、链表与回溯","level":"中等","priority":"高频","type":"编程","title":"网格中查找指令词","question":"最多 12×12 的字母网格，从任意格出发沿四方向移动，不能重复使用格子，判断能否拼出非空词，长度 L≤18。","example":"网格 [[A,B],[D,C]]，词 ABCD → YES","answer":"以匹配首字母的格为起点 DFS。每步标记，回溯时撤销；先用字符总量过滤不可能的词。","complexity":"时间上界 O(RC·3^L)，空间 O(RC+L)。","track":"algo"},{"id":"alg058","topic":"树、链表与回溯","level":"进阶","priority":"拓展","type":"编程","title":"二叉树快照序列化","question":"二叉树节点为任意 32 位整数，n≤10^5。设计可往返的文本格式并说明解码策略。","example":"树 [7,null,-2] → 7,#,-2,#,#","answer":"前序输出数值及每个空节点的独立标记。解码用栈记录尚待填充的孩子位置，消费一项就填入位置，实节点提供两个新位置。","complexity":"时间 O(n)，迭代栈 O(h)，序列 O(n)。","traps":"仅用中序或忽略空节点通常无法唯一恢复形状。","track":"algo"},{"id":"alg059","topic":"工程数据结构与位运算","level":"中等","priority":"必刷","type":"编程","title":"实现固定容量 LRU 缓存","question":"提供 get(key) 和 put(key,val)，容量 C≥1。命中和写入都使该键变为最近使用，超容量淘汰最久未使用，未命中返回 -1。最多 10^5 次操作。","example":"C=2；put(1,8),put(2,9),get(1),put(3,1),get(2) → [8,-1]","answer":"哈希表定位节点，双向链表维护访问顺序。命中和更新移动到表头，新节点插表头，超容量淘汰表尾并删哈希表。","complexity":"期望每操作 O(1)，空间 O(C)。","traps":"更新已有键不新增节点；双哨兵减轻边界处理。","track":"algo"},{"id":"alg060","topic":"工程数据结构与位运算","level":"入门","priority":"高频","type":"编程","title":"一次出现的异常编号","question":"n≤10^5 个 32 位整数，除唯一一次出现的值外，其余每值恰出现两次，求异常编号。","example":"[7,12,7,4,12] → 4","answer":"对所有数做 XOR，成对元素归零，保留单值。","complexity":"时间 O(n)，空间 O(1)。","track":"algo"},{"id":"alg061","topic":"工程数据结构与位运算","level":"中等","priority":"高频","type":"编程","title":"按位处理两个异常编号","question":"n≤10^5 个整数，其中两个不同值各出现一次，其余每值出现两次，返回两个异常值（升序）。","example":"[4,7,4,8,2,8] → [2,7]","answer":"全体 XOR 得到两个异常值的异或，从该结果取一个为 1 的位，把数据按位分两组，各自 XOR 消去重复。","complexity":"时间 O(n)，空间 O(1)。","traps":"固定宽度语言可用无符号低位计算，避免有符号极小值取负溢出。","track":"algo"},{"id":"alg062","topic":"工程数据结构与位运算","level":"中等","priority":"高频","type":"编程","title":"在线统计节点前缀用量","question":"维护 n≤2×10^5 的整数数组，支持点增量和闭区间求和，各操作总数≤2×10^5。","example":"初始 [2,0,4]，求和(1,3)，增(2,5)，求和(2,3) → [6,9]","answer":"树状数组维护若干末尾区段的和。点增沿 i+=lowbit(i)，前缀和沿 i−=lowbit(i)，区间和为两个前缀之差。","complexity":"每次操作 O(log n)，空间 O(n)。","traps":"索引从 1 开始，0 的 lowbit 为 0。","track":"algo"},{"id":"alg063","topic":"工程数据结构与位运算","level":"进阶","priority":"拓展","type":"编程","title":"低开销接收已排序数据","question":"n≤10^5 个记录按给定顺序到达，统计序列中严格逆序的索引对数，即 i<j 且 a[i]>a[j]。","example":"[5,2,2,1] → 5","answer":"归并排序的合并阶段，若从右段取数且它小于当前左段首项，就累计左段尚未取走的元素数。","complexity":"时间 O(n log n)，空间 O(n)。","traps":"相等不计，左段先取；计数用 64 位。","track":"algo"},{"id":"alg064","topic":"工程数据结构与位运算","level":"进阶","priority":"拓展","type":"编程","title":"全部区间的最大吞吐动态查询","question":"给 n≤2×10^5 个用量值，支持单点赋值和区间最大值查询，总操作≤2×10^5，值可为负。","example":"初始 [3,-1,5]，查 [1,2]，置下标1为-2，查 [1,2] → [3,-1]","answer":"线段树每个节点存区间最大值。点更新后向上重算，区间查询用不交的覆盖节点合并，单位元为负无穷。","complexity":"建树 O(n)，单次 O(log n)，空间 O(n)。","track":"algo"},{"id":"alg065","topic":"数学与贪心","level":"入门","priority":"高频","type":"编程","title":"计算同步检查周期","question":"给两个正整数周期 a,b，1≤a,b≤10^9，求两者每轮对齐的最小正间隔。","example":"12,18 → 36","answer":"辗转相除求 gcd(a,b)，结果为 a/gcd(a,b)×b，除法优先以降低溢出风险。","complexity":"时间 O(log min(a,b))，空间 O(1)。","track":"algo"},{"id":"alg066","topic":"数学与贪心","level":"中等","priority":"高频","type":"编程","title":"批量计算重试方案数","question":"每层有 b 种独立重试策略，共 e 层。给 0≤b,e≤10^18，求 b^e mod (10^9+7)，约定 e=0 时结果为 1。","example":"b=3,e=5 → 243","answer":"快速幂从指数低位开始，当前位为 1 时乘当前底数；每轮底数平方后取模并右移指数。","complexity":"时间 O(log(e+1))，空间 O(1)。","track":"algo"},{"id":"alg067","topic":"数学与贪心","level":"中等","priority":"高频","type":"编程","title":"分配容器双任务槽","question":"n≤10^5 个任务，权重不超过容量 C。每个资源槽至多放两个任务、总权重≤C，求最少槽数。","example":"权重 [1,2,4,5], C=6 → 2","answer":"排序。每轮最重任务必须占一槽，如果它能与最轻任务配对就一起放，否则最重单独放。","complexity":"时间 O(n log n)，额外空间取决于排序。","traps":"限制至多两件；一般装箱不能套这个贪心。","track":"algo"},{"id":"alg068","topic":"数学与贪心","level":"进阶","priority":"拓展","type":"编程","title":"最小化作业合并成本","question":"给 n≤10^5 份正大小的已编码数据，每次任选两份合并，成本为两份之和，直到只剩一份，求总成本最小值。","example":"[2,3,7,8] → 37","answer":"每轮最小堆取两份最小值合并，成本累加，再把合并结果放回堆。对应 Huffman 的贪心合并。","complexity":"时间 O(n log n)，空间 O(n)。","traps":"本例依次合并 2+3=5、5+7=12、8+12=20。","track":"algo"},{"id":"alg069","topic":"数学与贪心","level":"中等","priority":"高频","type":"编程","title":"计算定额的窗口补齐次数","question":"给非负需求数组 n≤10^5，可在单次操作中给恰好 k 个连续位置各加 1，从全零出发匹配数组。求操作次数，不可达返回 -1。","example":"a=[2,3,1,0], k=2 → 3","answer":"从左到右维护此前启动窗口的累计覆盖，用差分撤销到期窗口。当前位置的缺额强制决定新开几次窗口；缺额为负或不能放下窗口却有缺额则失败。","complexity":"时间 O(n)，空间 O(n)。","track":"algo"},{"id":"inf001","topic":"Linux 与操作系统","level":"入门","priority":"必刷","type":"问答","title":"进程、线程和协程怎么选","question":"写一个推理网关，既有网络请求，也有耗时的纯 Python 预处理。三种执行模型如何分工？","example":"100 个连接同时等待上游，其中 10 个请求要做 CPU 密集特征提取。","answer":"进程有独立地址空间，隔离更强但通信和切换有成本；同进程线程共享内存，适合阻塞 I/O 或释放 GIL 的原生计算；协程需在可等待点主动让出，适合高并发 I/O。事件循环负责网络，用有界进程池处理实测为纯 Python 的 CPU 热点；原生扩展是否释放 GIL 先测。","traps":"别在事件循环里执行大循环；不要假定所有 Python 运行时和构建都有相同 GIL 行为。","track":"infra"},{"id":"inf002","topic":"Linux 与操作系统","level":"入门","priority":"高频","type":"问答","title":"虚拟内存、缺页和 RSS","question":"为什么 Python 加载 20 GiB mmap 模型文件后，RSS 不一定立刻上涨 20 GiB？","example":"首次访问 1 GiB 中相隔 4 KiB 的页面。","answer":"mmap 先建立虚拟地址范围；首次真正访问触发建页。如果数据已在页缓存，通常无需磁盘读，否则发生需要 I/O 的缺页。RSS 是进程当前驻留内存，文件页可能同其他进程共享；对共享页公平分摊可看 PSS。用 smaps_rollup、缺页统计及磁盘监控交叉验证。","traps":"不要把 VIRT 当作物理用量；内核预读和已有映射会改变结果。","track":"infra"},{"id":"inf003","topic":"Linux 与操作系统","level":"中等","priority":"必刷","type":"排障","title":"容器退出码 137 怎么定位","question":"训练容器突然退出 137。如何区分容器 OOM、节点 OOM 与手动终止？","example":"容器内存上限 16 GiB，设备显存只用了 60%。","answer":"137 常表示收到 SIGKILL；先看 Pod 上一实例的 lastState.terminated.reason、事件及节点日志。cgroup v2 可查 memory.events 的 oom/oom_kill 计数变化、memory.current/peak 和限制；结合节点内核 OOM 日志及运维操作记录。确认是哪层后再减 worker、缓存或 batch，或者调整经过验证的内存预算。","traps":"137 不足以证明 OOM；设备显存 OOM 与主机 cgroup OOM 要分别查。","track":"infra"},{"id":"inf004","topic":"Linux 与操作系统","level":"中等","priority":"高频","type":"排障","title":"CPU 很空但训练还是慢","question":"8 卡训练速度掉到一半，宿主机 CPU 平均使用率 15%。你如何确认是 CPU 限流、I/O 还是设备同步？","example":"单个 rank 的 step time 每隔一段时间尖刺。","answer":"按 rank 拆 data wait、H2D、forward、backward、collective。查每核与线程负载、容器 cpu.stat 的 nr_throttled/throttled_usec 变化、CPU affinity 和 NUMA；用 iostat、PSI、队列深度看 I/O；看设备时间线中 stream 的空洞和同步点。用已驻内存合成数据做对照，每次只改一个变量。","traps":"全机平均会掩盖单线程、单 NUMA 节点和 cgroup 限流。","track":"infra"},{"id":"inf005","topic":"Linux 与操作系统","level":"中等","priority":"高频","type":"问答","title":"阻塞 I/O 与 epoll 边沿触发","question":"为什么边沿触发读到一条消息就返回可能丢掉后续处理机会？如何应对忙连接挤占循环？","example":"fd 一次到达三帧，事件循环每次尝试只读一帧。","answer":"设 fd 非阻塞；通常循环读至 EAGAIN/EWOULDBLOCK，EINTR 继续，读到 0 按关闭处理。若为公平提前用完读预算，应显式加入应用层就绪队列或正确使用重置机制，确保仍可继续读。状态机保留半帧和多帧。","traps":"边沿触发的事件与应用层帧不一一对应。","track":"infra"},{"id":"inf006","topic":"Linux 与操作系统","level":"中等","priority":"必刷","type":"编程","title":"有界阻塞队列与优雅关闭","question":"用 mutex 和两个条件变量实现 push/pop/close。容量为 K，关闭后不能 push，已入队元素仍允许读完。给关键伪代码。","example":"容量 1；push(7)、close()、pop() 返回 7，下一次 pop() 返回 EOF。","answer":"持锁检查条件。push 在 while full && !closed 时等 notFull；关闭则失败，否则入队并唤醒 notEmpty。pop 在 while empty && !closed 时等 notEmpty；空且关闭返回 EOF，否则取出并唤醒 notFull。close 持锁标 closed 并广播两个条件变量。容器可用 deque 或环形缓冲。","complexity":"每次 O(1) 队列操作，空间 O(K)。","traps":"用谓词循环处理虚假唤醒；容量要求 K>0；关闭必须唤醒生产者。","track":"infra"},{"id":"inf007","topic":"Linux 与操作系统","level":"中等","priority":"高频","type":"问答","title":"锁、原子和线程可见性","question":"线程 A 写 result 后设置 ready，线程 B 等待 ready 后读 result。C++ 中为什么普通 bool 或 volatile 不够？给一个正确实现。","example":"单生产者、单消费者，每个对象只发布一次。","answer":"普通 bool 的并发读写产生数据竞争；volatile 不建立线程间同步。A 写 result 后对 atomic ready 执行 release store，B 以 acquire load 观察到该 true，发布前写入才对 B 可见。也可用共同 mutex 加条件变量。对象生命周期必须覆盖读写。","traps":"若要反复发布，单个布尔位不足，需额外协议或队列。","track":"infra"},{"id":"inf008","topic":"Linux 与操作系统","level":"中等","priority":"高频","type":"编程","title":"避免双锁转账死锁","question":"实现 transfer(src,dst,amount)，每个账户有互斥锁。如何防止 A→B 与 B→A 死锁，并保证余额一致？","example":"A=10 B=5，并发 A→B 4 与 B→A 2，均成功后 A=8 B=7。","answer":"先校验金额及同账户语义。对不同账户按不可变且唯一的账户 ID 顺序上锁，或使用支持死锁规避的 std::scoped_lock 同时拿两把锁；持两锁校验余额并同时更新，使用 RAII 释放。余额计算检查溢出。","complexity":"每次 O(1)，不计锁等待。","traps":"锁顺序必须是全局约定；同一 mutex 不能拿两次。","track":"infra"},{"id":"inf009","topic":"Linux 与操作系统","level":"进阶","priority":"拓展","type":"排障","title":"NUMA 与 CPU 亲和性","question":"同一台机器换两张卡，数据搬运吞吐明显变差。怀疑 CPU、内存和设备不在同一个 NUMA 域，如何验证？","example":"两个 CPU socket，设备分布在不同 PCIe 根复合体。","answer":"用 lspci 拓扑、sysfs 的 numa_node 和设备工具找设备亲近的节点。固定工作线程和内存位置，先取得本地/远端带宽与延迟基线；记录 numastat、内存带宽及设备利用率，再比较 first-touch、绑核和内存分配策略前后是否有改善。","traps":"只绑 CPU 未必迁移已有内存；绑得过紧也可能减少可用核或带宽。","track":"infra"},{"id":"inf010","topic":"Linux 与操作系统","level":"中等","priority":"高频","type":"编程","title":"从日志流统计错误峰值","question":"按时间戳递增输入日志，输出每一条 ERROR 到达时过去 60 秒内的错误数。窗口取 (t−60,t]。如何处理同秒多条？","example":"ERROR@0, ERROR@10, INFO@40, ERROR@60，输出 1,2,2。","answer":"用 deque 保存 ERROR 时间戳，遇 ERROR 时先弹出 ≤ t−60 的时间戳，再追加 t 并输出长度；同秒的记录逐条累加。可跳过 INFO 或顺手清理。若日志乱序，需先明确水位和迟到策略。","complexity":"O(N) 时间，O(W) 空间，W 为窗口内最多错误条数。","traps":"注意区间开闭；不能用一个普通时间戳集合去重。","track":"infra"},{"id":"inf011","topic":"网络与 RPC","level":"入门","priority":"必刷","type":"问答","title":"TCP 字节流和消息边界","question":"请求用 TCP 发送 4 字节长度加 JSON。一次 recv 能否读完一条？接收端要维护什么？","example":"一次得到完整帧和下一帧的前 2 个字节。","answer":"TCP 提供按序字节流，recv 可返回部分头、部分体或多帧。保留读缓冲和当前解析位置；攒齐头后按网络字节序取长度并做上限校验，攒齐消息体后交给解析器，剩余字节继续处理。EOF 时半帧表示截断。","traps":"校验长度再分配内存；发送也要处理短写与断连。","track":"infra"},{"id":"inf012","topic":"网络与 RPC","level":"中等","priority":"高频","type":"编程","title":"实现可取消的限流重试","question":"为幂等 RPC 写重试框架：总 deadline 为 D，仅重试部分临时错误，避免所有客户端同时重试。","example":"原始超时 800 ms，第 1 次耗时 500 ms 后发生瞬时失败。","answer":"记录单调时钟的 deadline；每次以剩余时间约束调用和下一次等待。仅对策略允许的瞬时失败重试，保证幂等性；以 capped exponential backoff 加 full jitter，设重试次数/预算，并监听取消。必要时尊重在 deadline 内的 Retry-After。","complexity":"O(R) 次尝试，R 受预算约束。","traps":"每次重试不应重新获得完整 800 ms；重复提交要有幂等键与服务端去重。","track":"infra"},{"id":"inf013","topic":"网络与 RPC","level":"中等","priority":"高频","type":"排障","title":"单机快跨机慢怎么分层查","question":"同样 8 张卡，单节点使用 8 卡比两节点各 4 卡快。你会怎么证明瓶颈来自跨机链路？","example":"假设吞吐为 1400 与 810 样本/秒。","answer":"先固定模型、有效 batch、设备型号和数据分片；用 profiler 比较 compute 与跨机 collective 暴露时间。再用合成 buffer 在同节点/跨节点测试同大小消息，检查拓扑、选中的接口、带宽、重传及网卡错误/拥塞计数。做消息大小扫描和每节点对照，区分带宽上限、延迟与慢 rank。","traps":"一次 ping 往返时延不能代表训练通信链路表现。","track":"infra"},{"id":"inf014","topic":"网络与 RPC","level":"中等","priority":"高频","type":"问答","title":"背压为什么优于无限排队","question":"推理服务以 120 req/s 到达，只能稳定处理 100 req/s。怎样设计降级，并保护已有请求？","example":"有 200 的开放队列，持续过载 5 秒。","answer":"长期输入超过服务能力，队列持续增长，直接推高尾延迟，直到内存或 deadline 耗尽。限制队列、并发和 token 总量，部署 admission control，及时拒绝并给客户端退避建议；尽早清理过期和取消任务，按成本或租户设置配额。","traps":"无拒绝的“大队列”只在短暂波峰足够时有用；重试可能放大负载。","track":"infra"},{"id":"inf015","topic":"网络与 RPC","level":"中等","priority":"拓展","type":"问答","title":"RDMA、RoCE 和拥塞","question":"为什么使用 RDMA 的多机训练仍可能被网络拖慢？请从数据路径与拥塞机制解释。","example":"单流测试达到线速，多流 AllReduce 时尾延迟飙升。","answer":"RDMA 可以降低端点数据搬运和 CPU 开销，但共享链路依旧有拥塞、队列、路由与拓扑限制。RoCE 常配合 ECN 和相应拥塞控制；采用 PFC 的部署还应检查 pause 及拥塞传播。对齐发送端、交换机和接收端指标，用集合测试验证不同流量模式。","traps":"目标是定位丢包和排队根因，不能见慢就调整 PFC。","track":"infra"},{"id":"inf016","topic":"分布式训练","level":"入门","priority":"必刷","type":"问答","title":"四种集合通信手算","question":"rank0=[1,2]，rank1=[3,4]。分别写出 AllReduce(SUM)、AllGather、ReduceScatter(SUM)、Broadcast(root=1) 的输出。","example":"均按 rank 顺序、等长切分。","answer":"AllReduce：两 rank 均 [4,6]。AllGather：两 rank 均 [1,2,3,4]。ReduceScatter：rank0 得 [4]，rank1 得 [6]。Broadcast：两 rank 均 [3,4]。还要能区分 All-to-All：各 rank 把按目标切分的片发送给不同 rank。","traps":"AllGather 不做数值相加；ReduceScatter 的切片由输出 rank 决定。","track":"infra"},{"id":"inf017","topic":"分布式训练","level":"中等","priority":"必刷","type":"问答","title":"Ring AllReduce 通信量推导","question":"P 个 rank，每个 rank 初始 1 个 M 字节张量，均匀切块。推导 Ring AllReduce 每 rank 的发送量和通信步数。","example":"P=4，M=64 MiB。","answer":"先用 ReduceScatter 的 P−1 步形成结果分片，再用 AllGather 的 P−1 步扩散。每步各 rank 发并收一块 M/P 字节，各自发送 2(P−1)M/P，接收同量；例为每 rank 发送 96 MiB、接收 96 MiB，6 步。按每步启动延迟 α 和单位字节时间 β，可粗略写 2(P−1)α+2(P−1)Mβ/P，忽略重叠和规约开销。","complexity":"2(P−1) 步，每 rank 发送 2(P−1)M/P 字节。","traps":"区分每 rank 与全局流量，也区分单向发送与收发总和。","track":"infra"},{"id":"inf018","topic":"分布式训练","level":"中等","priority":"必刷","type":"排障","title":"AllReduce 挂住找第一个异常 rank","question":"多卡作业在第 500 步 collective 超时，一个 rank 在第 499 步 OOM。如何定位因果？","example":"其余 rank 日志都显示等待 AllReduce。","answer":"先按 rank、全局步和 collective 序号对齐时间线，找最早失败的 rank。确认所有 rank 使用相同 communicator、调用次序及匹配的数据类型和形状；核对输入数量、条件分支、异常退出和数据尾部。用小规模最小复现验证，再排查设备和网卡。","traps":"其余 rank 的超时通常是连带结果；提高超时阈值不能补齐缺席 rank。","track":"infra"},{"id":"inf019","topic":"分布式训练","level":"入门","priority":"必刷","type":"问答","title":"DDP、TP、PP、FSDP 如何分工","question":"一个 40B 模型单卡放不下。解释数据并行、张量并行、流水线并行和 FSDP 各切什么，代价是什么。","example":"同样 8 张卡，机内和跨机带宽不同。","answer":"DDP 复制模型，各处理数据分片并同步梯度；TP 切层内张量，通常有高频集合通信；PP 按层切阶段、用微批填流水线，有气泡和阶段负载均衡问题；FSDP 按策略分片参数、梯度和优化器状态，计算前后有参数聚合与梯度分片通信。先估内存，再按互联与通信频率选择组合。","traps":"FSDP 计算时可能临时聚合参数；DDP 不自动减小单卡模型驻留。","track":"infra"},{"id":"inf020","topic":"分布式训练","level":"中等","priority":"必刷","type":"问答","title":"全局批量与梯度累积","question":"数据并行组 8 rank，每 rank microbatch=4，累积 3 次。全局 batch 多大？DDP 怎样避免每个微批同步？","example":"同一优化器步的所有微批大小相同。","answer":"有效全局 batch=8×4×3=96。每步先清梯度；前 2 个微批的 forward 和 backward 都放在 DDP no_sync 内，每个损失按 3 缩放；第 3 个正常同步，再做 optimizer.step。微批或各 rank 样本数不同时按总样本数加权，不能机械地除以 3。","traps":"no_sync 的作用域要包住 forward；并行维度应使用数据并行组大小。","track":"infra"},{"id":"inf021","topic":"分布式训练","level":"中等","priority":"高频","type":"编程","title":"准确聚合分布式指标","question":"各 rank 验证集大小不同，设计 loss、accuracy 的归约。如何避开验证采样补齐的重复样本？","example":"rank0: 100 样本，80 正确；rank1: 20 样本，10 正确。","answer":"本地累计每样本 loss 的和、correct_count 和有效 count；以 SUM 归约这些值，最后除以全局有效 count，例准确率 90/120=75%。分布式验证使用不重复的分片，或追踪样本 ID/有效掩码排除补齐项。全局无样本按约定输出未定义。","complexity":"每 rank O(n_local) 处理，归约固定数量的标量。","traps":"不要直接平均 80% 和 50%；分类指标中 F1 也通常不能直接平均各 rank F1。","track":"infra"},{"id":"inf022","topic":"分布式训练","level":"中等","priority":"高频","type":"问答","title":"梯度通信与计算如何重叠","question":"为什么将梯度打成 bucket 可以减少通信等待？bucket 太大或太小怎么办？","example":"反向计算顺序与参数在模型中的注册顺序可能不同。","answer":"把多个小梯度合并，减少通信启动开销；bucket 中梯度准备完即可发起异步归约，同时计算其余层。太大导致启动过晚和尾部等待，太小则通信启动次数增加、带宽利用率差。看 profiler 中 collective 与 backward 重叠及最后一段未隐藏时间再调。","traps":"CUDA/NPU stream 异步提交不等于真正重叠，可能共享设备资源或串行依赖。","track":"infra"},{"id":"inf023","topic":"分布式训练","level":"进阶","priority":"拓展","type":"问答","title":"流水线气泡与阶段不均衡","question":"4 个流水线阶段、8 个微批。只考虑等长前向时段，估算第一阶段先完成后到最后阶段结束的总时槽与利用率。若一阶段慢两倍会怎样？","example":"每阶段和每微批耗时均为 1 槽，忽略反向和通信。","answer":"填充需要 P−1 槽，之后每槽完成一个微批，总计 m+P−1=11 槽；设备时槽利用率 m/(m+P−1)=8/11。若一阶段耗时两倍，稳态吞吐受最慢阶段限制，需要重划阶段、改微批或降低该段负载；训练的真实气泡还受调度、反向和通信影响。","traps":"8/11 只适用于题设的等速前向模型，不能直接套到任意 1F1B 实现。","track":"infra"},{"id":"inf024","topic":"分布式训练","level":"进阶","priority":"高频","type":"排障","title":"恢复训练能否接着跑","question":"8 rank 训练在保存检查点时有节点掉线。如何保证从最近完整检查点恢复，并说明要存哪些状态？","example":"上一个检查点各文件齐全，新检查点仅写完部分 rank 的分片。","answer":"保存模型、优化器、LR scheduler、AMP scaler、全局步与采样/数据游标，按需要保存各 rank RNG；分片写到新 checkpoint 目录，完成校验并由协调者最后发布 manifest/commit 标记，保留上一个完整版本。恢复只读取存在完整标记且校验通过的版本。改变 world size 时要求后端明确支持重分片与数据恢复。","traps":"仅保存模型可用于推理或热启，不能保证训练连续。","track":"infra"},{"id":"inf025","topic":"分布式训练","level":"进阶","priority":"拓展","type":"问答","title":"MoE 为什么大量用 All-to-All","question":"MoE 把专家分散在 4 张卡，各 token top-2 路由。前向需要怎样移动数据？如何处理热点专家？","example":"一半 token 被派到同一专家。","answer":"每 rank 将 token 根据目标专家所在 rank 打包，交换分段计数并用 All-to-All 类通信分发；专家计算后再将结果按原 token/路由索引返回并加权合并。热点抬高单 rank 算力和网络尾延迟，可用负载均衡损失、容量策略、专家布局或复制。","traps":"top-2 有复制与索引回填；限制容量会改变路由和有效结果，需明确。","track":"infra"},{"id":"inf026","topic":"加速器与昇腾","level":"入门","priority":"必刷","type":"问答","title":"Host、Device、Stream、Event","question":"解释四者，并给出 H2D→kernel→D2H 的最小依赖关系。","example":"H2D 在拷贝 stream，kernel 在计算 stream。","answer":"Host 提交工作，Device 执行；同一 stream 的工作通过入队顺序建立依赖，不同 stream 需要事件或其他显式依赖。H2D 后记录 E1，计算 stream 等 E1 再运行 kernel，kernel 后记录 E2，拷回 stream 等 E2；Host 在读回传数据前等待完成。","traps":"异步 API 成功可能只表示提交；完成前不得复用/释放相关缓冲区。","track":"infra"},{"id":"inf027","topic":"加速器与昇腾","level":"中等","priority":"必刷","type":"问答","title":"昇腾的软件栈各层做什么","question":"将 PyTorch 的训练作业移植到昇腾时，怎么解释 CANN、AscendCL、HCCL、Ascend Extension for PyTorch，各自在哪一层？","example":"模型需跑 eager 训练并使用多 NPU 同步。","answer":"CANN 提供昇腾加速计算所需的基础软件栈；AscendCL 属于应用 API 层，用于运行时资源、内存、流、模型或算子等操作；HCCL 负责昇腾设备上的集合通信；Ascend Extension for PyTorch 提供 PyTorch 对 NPU 的设备与算子适配，并接入 HCCL。实际适配先核对设备、驱动/固件、CANN、扩展及 PyTorch 的兼容组合。","traps":"框架版本与 NPU 扩展版本都需要对照实际兼容矩阵。","track":"infra"},{"id":"inf028","topic":"加速器与昇腾","level":"中等","priority":"必刷","type":"编程","title":"写一个两卡 HCCL 求和实验","question":"用伪代码为两个 rank 各自输入 [rank+1, 2]，完成设备 AllReduce 并验证输出。标出初始化、同步和清理位置。","example":"正确结果在两个 rank 均为 [3,4]。","answer":"绑定本地设备并创建 stream；用共享的初始化信息和唯一 rank 建相同成员的 communicator；分配输入/输出设备缓存，将本 rank 数据拷入。两端按相同顺序调用 HcclAllReduce，count=2、dtype=FP32、op=SUM；等待 stream 或用有依赖的 D2H 并同步后，在 Host 验证结果。所有步骤查返回码，完成后按资源依赖清理。","traps":"所有 rank 的 count、dtype、op 必须匹配；rank 与 device ID 不可默认等同。","track":"infra"},{"id":"inf029","topic":"加速器与昇腾","level":"中等","priority":"高频","type":"问答","title":"显存带宽、计算吞吐与 Roofline","question":"算子每秒计算上限 60 TFLOP/s，内存带宽 1 TB/s，算术强度 20 FLOP/byte。理论吞吐受哪项约束？优化方向是什么？","example":"采用十进制单位，忽略其他瓶颈。","answer":"带宽上限为 20 TFLOP/s，小于计算上限 60 TFLOP/s，理想模型下受带宽约束。比较实际吞吐与有效带宽；融合操作、减少物化中间张量，提高缓存/片上复用并改善访存布局。再看 launch、并行度和设备时间线。","complexity":"理想上界 min(P_peak, BW×I)。","traps":"FLOP/byte 的字节数应对应你分析的内存层级。","track":"infra"},{"id":"inf030","topic":"加速器与昇腾","level":"中等","priority":"高频","type":"问答","title":"内存分页锁定与双缓冲","question":"两个批次交替使用两块 Host 和 Device buffer，怎样让传输与上一批计算重叠？","example":"GPU 平台；Host 内存支持 pinned allocation。","answer":"采用有限数量的 pinned buffers，拷贝与计算放在两个 stream 上。每块 buffer 的 H2D 完成事件解锁本批计算，计算完成事件解锁设备 buffer 的下一次覆写；Host buffer 需等 H2D 不再读取再重填。实际重叠依赖硬件拷贝引擎、传输方向和无资源冲突。","traps":"Host 提交下一批不等于设备并行；过量 pinned memory 会压缩系统可管理内存。","track":"infra"},{"id":"inf031","topic":"加速器与昇腾","level":"进阶","priority":"高频","type":"编程","title":"分块矩阵乘法的内存推导","question":"给出矩阵乘 C[M,N]=A[M,K]·B[K,N] 的三层 tile 循环。一个输出块为 bm×bn，K 维分块 bk，片上至少要放哪些数据？","example":"非整除的边缘 tile 也要正确。","answer":"按 i、j 遍历输出 tile；将 bm×bn 累加块清零，按 k 遍历内维 tile，将 A 子块、B 子块加载到片上，乘加至累加块，最后一次写回。边缘用有效范围或零填充掩码。单缓冲最低元素数约 bm·bk+bk·bn+bm·bn，各项按输入/累加 dtype 计算字节；双缓冲额外容纳下一组输入。","complexity":"O(MNK) 算术计算；每 tile 片上空间如上。","traps":"累加精度可能与输入类型不同；片上可用容量还有对齐等约束。","track":"infra"},{"id":"inf032","topic":"加速器与昇腾","level":"中等","priority":"高频","type":"排障","title":"昇腾算子报“不支持”怎么查","question":"同一个模型在 CUDA 上能跑，切到 NPU 之后某层报算子参数不支持或后端失败。怎样把问题缩小到可复现范围？","example":"训练只在动态 batch 和某一种 dtype 下失败。","answer":"抓首个失败算子的名称、shape、dtype、layout 与调用栈；构造最小 tensor 示例并对比固定 shape/dtype、连续性和 eager/图模式。核对模型算子支持列表与版本矩阵，并先测试等价改写或受控的 dtype 调整，验证数值和性能。","traps":"避免先批量替换所有算子；CPU 回退如发生还可能隐含同步或复制。","track":"infra"},{"id":"inf033","topic":"加速器与昇腾","level":"进阶","priority":"拓展","type":"排障","title":"异步报错出现在下一行","question":"设备 kernel 实际在 A 处出错，应用日志却在 B 处提示同步失败。如何定位且不把调试开销留在生产？","example":"A 后有多次异步调用，B 第一次等待设备。","answer":"调用返回成功可能仅代表任务已排队；错误可在随后的同步点被观察。保留逐调用信息，调试时对疑似段插入 stream 同步并二分缩小范围，再用设备工具查看异常和 trace。修复后去掉额外同步，重新跑正确性和性能基线。","traps":"全局同步改变并行时序，可能掩盖竞态，不能作为生产修复。","track":"infra"},{"id":"inf034","topic":"PyTorch 与数值","level":"入门","priority":"必刷","type":"问答","title":"eval 与 inference_mode 的区别","question":"线上推理用了 model.eval()，显存仍偏高。eval()、no_grad()、inference_mode() 分别影响什么？","example":"模型中含 BatchNorm 和 Dropout。","answer":"eval() 切模型模块的训练状态，影响 Dropout 和 BatchNorm 等行为；no_grad() 让区域内普通运算不记录反向图；inference_mode() 进一步省去部分 autograd 跟踪开销，对所得张量重新参与梯度计算有更多限制。推理通常把 eval() 与合适的梯度模式一起用。","traps":"eval() 不关闭梯度；no_grad() 也不会自动切换 Dropout。","track":"infra"},{"id":"inf035","topic":"PyTorch 与数值","level":"中等","priority":"必刷","type":"编程","title":"稳定 Softmax 和交叉熵","question":"给出稳定的 softmax 与单样本交叉熵计算式，说明如何处理大数。","example":"logits=[1000,1001,1002]，正确类别索引 2。","answer":"计算 m=max(x)，s=sum(exp(x_i−m))，softmax_i=exp(x_i−m)/s，loss=(m−x_y)+log(s)。样例约 [0.0900,0.2447,0.6652]，loss≈0.4076。低精度输入可用 FP32 求和；所有位置均被掩码的语义应提前定义。","complexity":"O(N) 时间，输出 O(N)，只算 loss 时 O(1) 额外空间。","traps":"别直接对 1002 求 exp；优先用融合的 log-softmax/cross-entropy。","track":"infra"},{"id":"inf036","topic":"PyTorch 与数值","level":"中等","priority":"必刷","type":"问答","title":"FP16、BF16 和 GradScaler","question":"混合精度时训练出现 NaN 或梯度消失。FP16、BF16 有什么区别？为什么 FP16 通常要做 loss scaling？","example":"某些小梯度在转换到 FP16 时变成 0。","answer":"BF16 指数位与 FP32 相同，动态范围更大但尾数位少；FP16 范围较小，loss scaling 放大反向梯度降低下溢风险。更新前 unscale 并做溢出检查，若溢出跳过步并回调 scale；梯度裁剪应在 unscale 后。定位非有限值最早出现的算子，核对数据、学习率和关键规约精度。","traps":"loss scaling 无法修复前向溢出；BF16 并非在所有硬件、算子或任务都更快。","track":"infra"},{"id":"inf037","topic":"PyTorch 与数值","level":"中等","priority":"高频","type":"排障","title":"DataLoader 喂不满卡","question":"设备利用率周期性掉到 0，GPU/NPU 计算本身耗时稳定。怎样验证并修 DataLoader 瓶颈？","example":"记录发现每 8 步等待下一批 400 ms。","answer":"拆取 batch、解码/增强、拷贝和计算计时；固定随机性，换内存合成数据验证。逐步调整 worker、预取、持久 worker、适用设备上的 pin memory、数据打包和 CPU 亲和性；监控宿主机内存、共享内存、文件句柄与单 rank 分片。","traps":"worker 不是越多越好；分布式中 worker 数乘 rank 数。","track":"infra"},{"id":"inf038","topic":"PyTorch 与数值","level":"中等","priority":"高频","type":"排障","title":"训练显存逐步上涨","question":"显存不是第一步就爆，而是每 100 步上涨。找两个典型代码级原因并说明验证方法。","example":"循环中用了 losses.append(loss) 和每步保存模型输出做可视化。","answer":"检查是否在列表/回调保留了带梯度的张量或图，用适当的 detach 与转 CPU/取标量替代，并给缓存设限；排查 retain_graph、累积梯度或验证时未关闭梯度。比较活跃分配和 allocator 保留量，快照定位来源，并用最小长跑确认内存平台。","traps":"每步 item 可能引入设备同步；清 allocator 缓存也无法释放仍有引用的 tensor。","track":"infra"},{"id":"inf039","topic":"PyTorch 与数值","level":"中等","priority":"高频","type":"问答","title":"view、reshape、contiguous 与 stride","question":"一个 2×3 连续张量转置后调用 view(-1) 报错。为什么？三种接口怎么选？","example":"转置前 stride=(3,1)，转置后 stride=(1,3)。","answer":"转置通常共享底层存储，只改变 shape/stride。该布局无法用一维规律 stride 表示逻辑展平，view 前提不满足；reshape 优先 View，必要时复制；contiguous 明确保证所请求的连续布局后可 View。设备 profiler 可检验隐藏复制。","traps":"不要依赖 reshape 一定共享或一定新建内存；同一 storage 可以有不同 stride。","track":"infra"},{"id":"inf040","topic":"PyTorch 与数值","level":"中等","priority":"高频","type":"问答","title":"激活检查点的代价","question":"大模型训练在反向开始时 OOM，activation checkpointing 怎么减少峰值？与保存训练检查点有什么区别？","example":"模型包含 Dropout，要求结果与基线可比。","answer":"前向仅保留某些边界信息，反向时按需重算被丢弃的中间激活，做到用计算换设备内存；与用于作业重启的持久检查点不同。验证重算的 RNG、训练态、精度和副作用是否一致，先选择大而便宜的激活段，测峰值和每步时间。","traps":"它不直接缩小权重或优化器状态；跨设备 RNG 和副作用需要格外检查。","track":"infra"},{"id":"inf041","topic":"PyTorch 与数值","level":"进阶","priority":"拓展","type":"编程","title":"写可合并的在线均值和方差","question":"实现更新和两组状态合并。每组可用 Welford 状态 (n,mean,M2)，给合并公式，样本方差分母怎么取？","example":"组 A=[1,3]，组 B=[5,7]。","answer":"δ=meanB−meanA，n=nA+nB，mean=meanA+δ·nB/n，M2=M2A+M2B+δ²·nA·nB/n；遇空组返回另一组。单点更新即与 (1,x,0) 合并。样例 n=4，mean=4，M2=20，样本方差为 20/3，整体方差为 5。","complexity":"更新和合并 O(1) 时间/空间。","traps":"n≤1 时样本方差未定义；低精度下建议较高精度累计。","track":"infra"},{"id":"inf042","topic":"推理与服务","level":"入门","priority":"必刷","type":"问答","title":"Prefill、Decode、TTFT、TPOT","question":"用户说首字快，但之后文字出来慢。分别用哪些指标观察，并解释模型的两步？","example":"输入 2048 token，生成 200 token。","answer":"prefill 处理整段输入建立 KV，在 decoder-only 生成中产出首步 logits；decode 反复读取 KV 并生成新 token。TTFT 是发送至首 token（说明计时边界），包括排队与 prefill；TPOT 描述后续 token 生成平均时间，常用 (最后 token 时间−首 token 时间)/(输出 token数−1)，ITL 看逐 token 间隔。","traps":"只有 1 token 时 TPOT 不适用；长 prompt 对首字影响通常更大。","track":"infra"},{"id":"inf043","topic":"推理与服务","level":"中等","priority":"必刷","type":"问答","title":"KV cache 内存估算","question":"32 层模型，有 8 个 KV heads，每头 128 维，KV 为 BF16。每个 token 的 KV cache 多大？4096 token 多大？","example":"不考虑分片、元数据、padding 和复用。","answer":"每层每 token 有 K、V 两份，元素数 2×8×128，每元素 2 byte；32 层共 131072 byte=128 KiB/token。4096 token 为 512 MiB。并发按实际独占 token 求和；若跨组共享或按 TP sharding，按真实存储布局折算。","traps":"GQA 用 KV heads 数，不能把 query heads 代入；cache 不等于全部显存。","track":"infra"},{"id":"inf044","topic":"推理与服务","level":"中等","priority":"必刷","type":"问答","title":"连续批处理与动态批处理","question":"生成速度不同的请求为何让静态 batch 浪费？连续批处理如何调度以及怎样控制尾延迟？","example":"A 生成 5 token，B 生成 200 token，中途有 C 到来。","answer":"若静态 batch 定员到整个批次结束，A 停后槽空；连续批处理以每个生成迭代重组活跃请求，A 完成即回收资源，C 可在预算允许时补位。设置每轮 token/序列预算，适当切分 prefill，兼顾短请求和 decode 延迟，监测 TTFT、ITL 和吞吐。","traps":"放大 batch 可能提高吞吐，也可能提高等待延迟；并发请求数与 token 数是不同的预算。","track":"infra"},{"id":"inf045","topic":"推理与服务","level":"中等","priority":"高频","type":"问答","title":"PagedAttention 与前缀复用","question":"为什么分页式 KV 管理能容纳更多长短不一的请求？哪些请求可以共享前缀？","example":"每块 16 token，一条请求最终使用 34 token。","answer":"KV 切成固定 token 数的块，通过表将逻辑位置映射到任意物理块，按需增长；34 token 占 3 块，最多有 14 token 位置空余。符合相同模型/版本、相关参数、相同 token 前缀且满足隔离策略的请求可复用前缀块；共享块通常采用引用计数和必要时写时复制。","traps":"块减少外部碎片，最后一块仍有内部碎片；缓存是否跨租户共享取决于安全策略。","track":"infra"},{"id":"inf046","topic":"推理与服务","level":"中等","priority":"高频","type":"编程","title":"截止时间感知的动态批处理","question":"写一个单模型批处理伪代码。最大请求数 B，并限制总 token；每个请求带 deadline，不能等满才发。","example":"B=4，第一请求到达后最多等 8 ms，遇接近截止的请求应立刻评估。","answer":"队列保留到达时间和截止时间；从首请求到达起计时，按可装入请求与 token 预算组 batch。当满、等待窗口到、或最早 deadline 扣除预计服务时间后剩余不足，则发车。落队前剔除过期/取消请求，做过载拒绝并维护公平性，完成后按请求 ID 拆回结果。","complexity":"普通队列每条 O(1) 操作；需要按 deadline 优先时可用 O(log Q) 堆。","traps":"要考虑服务时间和预算而不只考虑入队延迟；超长请求应有独立策略。","track":"infra"},{"id":"inf047","topic":"推理与服务","level":"中等","priority":"高频","type":"问答","title":"INT8、INT4 如何验收","question":"一次量化后权重内存变小，但端到端速度没改善。如何解释和验证？","example":"输入长度主要是 32−128 token，并发不高。","answer":"权重量化缩小权重驻留与读取，但启用何种 kernel、反量化开销、设备支持、batch 和实际瓶颈决定速度；KV 和激活内存未必改变。固定输入分布比较模型质量、首 token、后续 token、吞吐和设备峰值，检查 profiler 是否选用优化 kernel。","traps":"量化位数不能直接推出加速倍数；离群值、校准样本和精度限值都要考虑。","track":"infra"},{"id":"inf048","topic":"推理与服务","level":"进阶","priority":"高频","type":"排障","title":"长请求拖累短请求 P99","question":"服务吞吐看起来不变，短请求 P99 昨天翻了三倍。日志显示突然出现更多长输入。怎样捕获并隔离问题？","example":"同一队列混合 256 和 16384 token 输入。","answer":"按输入长度、并发和租户分桶，观察队列等待、TTFT、ITL、cache 压力与 prefill 时段。回放流量分布复现；评估分池/限额、按 token 成本调度、分块 prefill 或更严格的入队预算；报告短长两组延迟与整体 goodput。","traps":"不能只看全体平均值；给短请求绝对优先可能饿死长请求。","track":"infra"},{"id":"inf049","topic":"推理与服务","level":"进阶","priority":"拓展","type":"问答","title":"推测解码什么时候快","question":"draft 模型先猜 k 个 token，由主模型验证。为什么有时更快，有时反而变慢？","example":"接受率很低，同时主模型已因高 batch 饱和。","answer":"一次主模型验证多个候选，接受率高时可减少串行主模型步数；收益需覆盖 draft、验证与调度成本。接受率低、batch 已饱和、内存不足或小模型本身很快时收益可能消失。若要求与原分布一致，采样需执行正确的接受和拒绝后重采样算法。","traps":"只保留相等的 argmax 不是通用的无损采样方案。","track":"infra"},{"id":"inf050","topic":"推理与服务","level":"进阶","priority":"拓展","type":"问答","title":"Prefill 和 Decode 分离部署","question":"什么时候值得把 prefill 和 decode 放在不同设备池？跨池切换最关键的成本是什么？","example":"长 prompt 主导 TTFT，持续生成主导 ITL。","answer":"独立设置分配比例、调度策略和设备类型，可减轻同池争用，并按两阶段负载扩容。代价是传输 KV cache、等待与编排，可能还需要处理布局不一致、传输失败、请求取消和 cache 回收。用端到端 goodput 验证搬运开销可接受。","traps":"拆池要考虑回压及池之间容量匹配；不要只看两个池各自的吞吐。","track":"infra"},{"id":"inf051","topic":"Kubernetes 与存储","level":"入门","priority":"必刷","type":"问答","title":"K8s Pod 为什么拿不到 GPU/NPU","question":"节点物理上有 8 卡，但申请 2 卡的 Pod Pending。先检查什么？","example":"Pod 声明了厂商扩展资源名，集群中还有其他卡作业。","answer":"先读 Pod 事件的 FailedScheduling 细节。核对资源名、节点 allocatable、已分配数、插件是否注册且设备健康，然后排查标签/affinity、taint/toleration、配额和拓扑限制。调度成功后设备不可见才继续查插件分配、容器运行时注入和驱动。","traps":"总空卡数不能解决单 Pod 必须同节点满足的要求；别只看物理 GPU 数。","track":"infra"},{"id":"inf052","topic":"Kubernetes 与存储","level":"中等","priority":"高频","type":"问答","title":"startup、readiness、liveness 怎么配置","question":"模型加载约 90 秒，线上偶尔仓库变慢。何时该下线流量、何时该重启实例？","example":"希望旧版本稳定服务，直到新实例完全预热。","answer":"startup probe 给初始化预算并防止其完成前执行常规存活/就绪检查；readiness 表示能接流量，失败时不再作为就绪端点；liveness 表示进程失去自恢复能力，持续失败可触发容器重启。将模型加载和预热作为就绪条件，避免把上游短暂异常无条件视为存活故障。","traps":"探针超时过小可能造成崩溃循环；就绪失败不会自动重启。","track":"infra"},{"id":"inf053","topic":"Kubernetes 与存储","level":"中等","priority":"高频","type":"问答","title":"训练任务的 Gang Scheduling","question":"分布式训练需要四个 worker 每个两卡。三个 worker 启动并等第四个，怎样避免白占六卡？","example":"两个不完整的训练任务各占了部分空闲设备。","answer":"组调度将最少可启动成员数作为整体准入条件，满足资源与拓扑后再允许一组启动；不足时排队并根据队列配额、优先级与策略处理。设 rendezvous 超时、失败清理和检查点策略，调度成功也不能替代运行时容错。","traps":"普通 Pod 独立调度不能保证组级准入；抢占前要考虑训练丢失进度。","track":"infra"},{"id":"inf054","topic":"Kubernetes 与存储","level":"中等","priority":"高频","type":"排障","title":"小文件把存储拖慢","question":"训练数据由数千万张小图片构成，设备并发越多，单卡吞吐越差，网络总带宽却没满。如何验证并改？","example":"热点来自对象存储 GET 与元数据操作。","answer":"监控 IOPS、请求速率、打开/查找开销、请求 P99、网络及缓存命中率；对照内存/本地数据。尝试把样本打包成合理大小的可流式读取分片，顺序预取，局部缓存和有界并发，保留训练所需随机性与可重现的数据分片。","traps":"大分片也可能降低并行调度或增加重试开销；别只测单 worker。","track":"infra"},{"id":"inf055","topic":"Kubernetes 与存储","level":"中等","priority":"高频","type":"编程","title":"实现训练数据分片器","question":"有 M 个样本，R 个 rank，每个 rank W 个 worker。给可复现的分片规则，要求单 epoch 不重不漏。","example":"M=10、R=2、W=2；写出每种 worker 的样本，设打乱顺序恰为 0..9。","answer":"先按 seed+epoch 产生同一全局顺序；全局 worker id=rank·W+worker_id，有 R·W 个 worker，每个从自己的位置起每隔 R·W 取一个。样例四组为 [0,4,8]、[1,5,9]、[2,6]、[3,7]。循环训练还要明确最后一批不足时如何保证所有 rank 执行匹配的 collective。","complexity":"生成完整排列通常 O(M) 时间/空间，每个 worker 遍历其分到的样本。","traps":"单 epoch 不重不漏与每 rank 相同步数可能冲突，量化尾部并显式解决。","track":"infra"},{"id":"inf056","topic":"Kubernetes 与存储","level":"进阶","priority":"拓展","type":"问答","title":"模型制品滚动发布和回滚","question":"5 台推理机都从远端拉模型，怎么避免读到一半版本？发布失败后怎样精确回滚？","example":"新模型含 tokenizer、32 个权重分片、配置文件。","answer":"不可变版本目录与 manifest 描述必需文件、校验和及关联 tokenizer/config；先下载到临时目录并验证，完整后再激活该版本。预热和健康检查后灰度，观察错误与 SLO，记录流量版本，出问题把路由切回已可用的上一个完整版本。","traps":"同名原地覆盖可能导致版本手动混读；保留回滚容量及冷启动时间预算。","track":"infra"},{"id":"inf057","topic":"性能与排障","level":"中等","priority":"必刷","type":"编程","title":"正确计时一个异步 kernel","question":"以下逻辑 t0=host_timer(); launch_kernel(); t1=host_timer() 会得到什么？写设备耗时与端到端耗时的两套计法。","example":"模型首轮会编译并初始化内存池。","answer":"原写法通常测到 host 提交时间。先做代表性 warmup。设备时间在相关 stream 前后记录设备事件，等待结束事件并求设备时差；端到端以单调时钟从请求入口到设备完成且结果真实可用，说明是否含排队/拷贝/预处理。采多次给出分位数和负载。","traps":"不要用全设备同步测跨 stream 每条请求而改变正常并发；区分冷启动与稳态。","track":"infra"},{"id":"inf058","topic":"性能与排障","level":"中等","priority":"必刷","type":"编程","title":"计算 P95、P99 与 goodput","question":"对 100 个延迟样本，采用 nearest-rank 求 P95、P99。若 10 秒内完成 100 请求、其中 82 个成功且满足 SLO，求 goodput。","example":"样本按升序排列，序号从 1 到 100。","answer":"排序后取第 ceil(0.95·100)=95 个和第 99 个样本；此题将 goodput 定义为成功且满足 SLO 的请求数/观测时长，即 8.2 req/s。开放环压测应记录到达、丢弃和超时，同时报告样本数与观测窗口。","complexity":"排序 O(N log N)，固定分位也可用选择算法。","traps":"P99 插值规则要先讲清；只统计成功响应可能把过载隐藏掉。","track":"infra"},{"id":"inf059","topic":"性能与排障","level":"中等","priority":"高频","type":"问答","title":"吞吐、延迟与并发的关系","question":"稳态服务吞吐 50 req/s，平均端到端 200 ms。估算系统中平均请求数。为什么并发继续放大未必提高吞吐？","example":"观测边界对齐且长期稳定，平均无丢失。","answer":"用 Little 定律 L=λW=50×0.2=10；这里 L 含正在服务和等待的平均请求数。并发超过瓶颈容量时主要增加排队时延，可能压低时延达标的 goodput。扫不同负载，并同时报告 p50/p99 和超时率。","traps":"必须匹配吞吐和延迟的统计边界；分位数不能直接代入 Little 定律。","track":"infra"},{"id":"inf060","topic":"性能与排障","level":"中等","priority":"高频","type":"问答","title":"怎么识别瓶颈迁移","question":"融合一个算子后其用时少了 50%，训练 step 只快 4%。给一个解释和两组验证。","example":"该算子在基线中技术上占 step 串行用时的 8%。","answer":"串行且其他不变时 step 从 100 降到 96，符合 4% 时间减少；加速比约 1.042。用时间线验证该算子是否在关键路径，检查通信、数据读取、同步是否接替瓶颈；分别做算子 microbenchmark 与完整作业端到端 A/B。","traps":"profiler 各类别求和可能含重叠时间，不能直接代替关键路径时长。","track":"infra"},{"id":"inf061","topic":"性能与排障","level":"进阶","priority":"高频","type":"排障","title":"压测报告胜了，线上却退化","question":"基准 A 比 B 的 tokens/s 高 30%，线上 TTFT P99 更差。写一套公平复测方案和判定标准。","example":"基准用固定长度，高并发，线上有突发和长尾上下文。","answer":"固定模型、精度、硬件、并行和 KV 上限；用开放环回放输入输出长度及到达模式，并单列冷启动/稳态。报告成功、超时、拒绝、吞吐、TTFT/ITL/E2E 分位及每 GPU/NPU 的 SLO goodput，按负载扫描到过载。判定以目标业务 SLO、质量和容量预算为准。","traps":"闭环测量可能漏报拥塞下本该到达的请求；自然输出长度差异也会影响可比性。","track":"infra"},{"id":"inf062","topic":"性能与排障","level":"进阶","priority":"拓展","type":"编程","title":"合并多实例的延迟直方图","question":"每台实例上报固定边界的非累计 bucket 计数，怎样得到全服务滚动 P99？","example":"两台需用相同边界，并提供相同时间窗内的观测计数。","answer":"按时间窗对齐，先按 bucket 做计数求和，计算 q=ceil(0.99×total)。从低到高累加，找到第一个达到 q 的 bucket，用上界作保守估计或明确分布假设后桶内插值。无样本、溢出桶和上报缺失要有显式策略。","complexity":"I 台、B 个桶时 O(I·B) 时间，O(B) 附加空间。","traps":"平均各实例 P99 不能得到全服务 P99；累计桶先转差分或采用累计求和并直接扫。","track":"infra"}];
